1	/**
2	 * Unit Conversion & Display — Pure functions for pack ↔ base-unit math
3	 * and human-readable stock formatting.
4	 *
5	 * All quantity storage in the system is pack-denominated (on_hand = number
6	 * of packs, possibly fractional). These helpers translate between "packs"
7	 * and "base units" so the UI can display and accept quantities in
8	 * whichever form is most natural for the guard.
9	 */
10	
11	import { resolveUnit, type UnitDef } from './registry';
12	
13	// ─── Rounding ────────────────────────────────────────────────────
14	
15	/**
16	 * Round a quantity to a clean precision, killing floating-point dust
17	 * (0.30000000000000004 → 0.3, 5.1000000000001 → 5.1). Three decimals
18	 * is the finest granularity the system tracks (the smallest minStep /
19	 * pack-correction floor is 0.001), so anything below that is noise.
20	 *
21	 * Use this on every value produced by pack↔unit conversion or by
22	 * grid-snapping before it lands in state or on screen — raw float math
23	 * leaks garbage digits that then get displayed verbatim by the stepper.
24	 */
25	export function roundQty(n: number, decimals: number = 3): number {
26	  const factor = Math.pow(10, decimals);
27	  return Math.round(n * factor) / factor;
28	}
29	
30	// ─── Conversion ──────────────────────────────────────────────────
31	
32	/** Convert a pack count to base units.  3 packs × 5 kg/pack = 15 kg. */
33	export function packToBase(packs: number, packSize: number): number {
34	  return packs * (packSize > 0 ? packSize : 1);
35	}
36	
37	/** Convert base units to fractional packs.  13 l ÷ 5 l/pack = 2.6 packs. */
38	export function baseToPack(baseUnits: number, packSize: number): number {
39	  const ps = packSize > 0 ? packSize : 1;
40	  return baseUnits / ps;
41	}
42	
43	// ─── Dispense Mode Resolution ────────────────────────────────────
44	
45	/**
46	 * Should the dispense UI show a pack/unit toggle?
47	 *
48	 * True when:
49	 *  - packSize > 1 (there IS a pack to subdivide), AND
50	 *  - the unit is continuous (kg, l — fractional amounts are meaningful),
51	 *    OR the unit is discrete but pack_size > 1 (3-bar pack → can take 1 bar)
52	 *
53	 * False when:
54	 *  - packSize ≤ 1 (single item = no subdivision)
55	 */
56	export function canSubdivide(
57	  packSize: number | null | undefined,
58	  unitSymbol: string | null | undefined,
59	): boolean {
60	  const ps = packSize ?? 1;
61	  if (ps <= 1) return false;
62	  // Any unit with pack_size > 1 can be subdivided — continuous units
63	  // allow decimal sub-amounts, discrete units allow integer sub-amounts.
64	  return true;
65	}
66	
67	/**
68	 * Whether the stepper should allow decimal input for a given mode.
69	 *
70	 * - In 'pack' mode: decimal only if the pack-level on_hand can be
71	 *   fractional (which it can when packs have been partially dispensed).
72	 *   We allow it to let guards correct fractional counts.
73	 * - In 'unit' mode: decimal only if the unit is continuous (kg, l).
74	 */
75	export function isDecimalMode(
76	  mode: 'pack' | 'unit',
77	  unitSymbol: string | null | undefined,
78	): boolean {
79	  const def = resolveUnit(unitSymbol);
80	  if (mode === 'unit') return def.nature === 'continuous';
81	  // Pack mode: allow decimal because fractional packs exist after
82	  // partial dispense (e.g. 2.6 cans). Guard can type 0.4.
83	  return true;
84	}
85	
86	/**
87	 * The step size the +/- buttons should use for a given mode.
88	 *
89	 * Pack mode: always 1 (one whole pack per tap).
90	 * Unit mode: uses the unit registry's minStep (0.1 for kg, 1 for bars).
91	 */
92	export function stepSizeFor(
93	  mode: 'pack' | 'unit',
94	  unitSymbol: string | null | undefined,
95	): number {
96	  if (mode === 'pack') return 1;
97	  return resolveUnit(unitSymbol).minStep;
98	}
99	
100	/**
101	 * Minimum value for the stepper.
102	 * Pack mode (continuous): 0 — fractional packs are real, and a clean 0
103	 *   floor lets the guard dial all the way down without the stepper
104	 *   snapping to an ugly 0.001. The confirm/save button gates on qty > 0
105	 *   separately, so 0 is a safe resting value, not a submittable one.
106	 * Pack mode (discrete): 1 — you can't take half a whole-count pack.
107	 * Unit mode: the unit's minStep (continuous) or 1 (discrete).
108	 */
109	export function minFor(
110	  mode: 'pack' | 'unit',
111	  unitSymbol: string | null | undefined,
112	): number {
113	  const def = resolveUnit(unitSymbol);
114	  if (mode === 'unit') return def.nature === 'continuous' ? def.minStep : 1;
115	  return def.nature === 'continuous' ? 0 : 1;
116	}
117	
118	/**
119	 * Maximum value for the stepper.
120	 * The available quantity re-expressed in the active mode.
121	 */
122	export function maxForMode(
123	  mode: 'pack' | 'unit',
124	  availablePacks: number,
125	  packSize: number | null | undefined,
126	): number {
127	  if (mode === 'pack') return availablePacks;
128	  return packToBase(availablePacks, packSize ?? 1);
129	}
130	
131	/**
132	 * Convert a value from one mode to the other.
133	 * Used when the guard toggles the pack/unit chip.
134	 */
135	export function convertBetweenModes(
136	  value: number,
137	  fromMode: 'pack' | 'unit',
138	  toMode: 'pack' | 'unit',
139	  packSize: number | null | undefined,
140	): number {
141	  if (fromMode === toMode) return value;
142	  const ps = (packSize ?? 1) > 0 ? (packSize ?? 1) : 1;
143	  if (fromMode === 'pack' && toMode === 'unit') return packToBase(value, ps);
144	  return baseToPack(value, ps);
145	}
146	
147	// ─── Display Formatting ──────────────────────────────────────────
148	
149	/**
150	 * Smart-round a number for display. Avoids ugly floating-point dust
151	 * (2.600000001 → 2.6) and keeps up to `maxDecimals` significant digits.
152	 */
153	function smartRound(n: number, maxDecimals: number = 2): number {
154	  if (Number.isInteger(n)) return n;
155	  const factor = Math.pow(10, maxDecimals);
156	  return Math.round(n * factor) / factor;
157	}
158	
159	/**
160	 * Format a single number for display, trimming trailing zeros.
161	 * 2.60 → "2.6", 3.0 → "3", 0.333 → "0.33"
162	 */
163	function formatNum(n: number): string {
164	  return String(smartRound(n));
165	}
166	
167	/**
168	 * Format on_hand for human-readable display.
169	 *
170	 * Handles four cases:
171	 *  1. packSize ≤ 1 → just `"15 kg"` or `"3 pcs"`
172	 *  2. Whole packs → `"3 packs"` (with unit hint: `"3 × 5 kg"`)
173	 *  3. Fractional continuous → `"2 packs + 3 l"` or `"13 l"`
174	 *  4. Fractional discrete → `"3 packs + 1 bar"`
175	 *
176	 * @param onHand   - Current stock in pack-denomination (may be fractional)
177	 * @param packSize - Units per pack (e.g. 5 for 5kg bags)
178	 * @param unit     - Unit symbol (e.g. 'kg', 'pcs')
179	 * @param style    - 'friendly' for app (2 packs + 3 l), 'compact' for dashboard (2.6)
180	 */
181	export function formatOnHand(
182	  onHand: number,
183	  packSize: number | null | undefined,
184	  unit: string | null | undefined,
185	  style: 'friendly' | 'compact' = 'friendly',
186	): string {
187	  const ps = (packSize ?? 1) > 0 ? (packSize ?? 1) : 1;
188	  const def = resolveUnit(unit);
189	  const rounded = smartRound(onHand);
190	
191	  // ─── Compact mode (dashboard) ────────────────────────────────
192	  if (style === 'compact') {
193	    if (ps <= 1) return `${formatNum(rounded)} ${def.symbol}`;
194	    return `${formatNum(rounded)}`;
195	  }
196	
197	  // ─── Pack size = 1: no pack/sub-unit split ───────────────────
198	  if (ps <= 1) {
199	    return `${formatNum(rounded)} ${def.symbol}`;
200	  }
201	
202	  // ─── Whole packs ─────────────────────────────────────────────
203	  if (Number.isInteger(rounded) || Math.abs(rounded - Math.round(rounded)) < 0.001) {
204	    const wholePacks = Math.round(rounded);
205	    if (wholePacks === 0) return `0 ${def.symbol}`;
206	    return `${wholePacks} × ${ps} ${def.symbol}`;
207	  }
208	
209	  // ─── Fractional packs ────────────────────────────────────────
210	  const wholePacks = Math.floor(rounded);
211	  const fractionalPacks = smartRound(rounded - wholePacks);
212	  const remainderBaseUnits = smartRound(fractionalPacks * ps);
213	
214	  if (def.nature === 'continuous') {
215	    // "2 packs + 3 l" or "3 l" if 0 whole packs
216	    if (wholePacks === 0) {
217	      return `${formatNum(remainderBaseUnits)} ${def.symbol}`;
218	    }
219	    return `${wholePacks} × ${ps} ${def.symbol} + ${formatNum(remainderBaseUnits)} ${def.symbol}`;
220	  }
221	
222	  // Discrete: "3 packs + 1 bar"
223	  const remainderInt = Math.round(remainderBaseUnits);
224	  if (wholePacks === 0) {
225	    return `${remainderInt} ${def.symbol}`;
226	  }
227	  if (remainderInt === 0) {
228	    return `${wholePacks} × ${ps} ${def.symbol}`;
229	  }
230	  return `${wholePacks} × ${ps} ${def.symbol} + ${remainderInt} ${def.symbol}`;
231	}
232	
233	/**
234	 * Short on-hand label for list items (stock picker, alerts).
235	 * Returns just the number + unit, e.g. "15 l" or "3".
236	 *
237	 * For pack_size > 1, shows the total in base units when the unit is
238	 * continuous, or the pack count otherwise.
239	 */
240	export function formatOnHandShort(
241	  onHand: number,
242	  packSize: number | null | undefined,
243	  unit: string | null | undefined,
244	): string {
245	  const ps = (packSize ?? 1) > 0 ? (packSize ?? 1) : 1;
246	  const def = resolveUnit(unit);
247	
248	  if (ps <= 1) {
249	    const u = def.symbol;
250	    return `${formatNum(smartRound(onHand))}${u ? ` ${u}` : ''}`;
251	  }
252	
253	  if (def.nature === 'continuous') {
254	    // Show total base units: 2.6 cans × 5 l = 13 l
255	    const total = smartRound(onHand * ps);
256	    return `${formatNum(total)} ${def.symbol}`;
257	  }
258	
259	  // Discrete with pack_size > 1: show pack count
260	  return `${formatNum(smartRound(onHand))}`;
261	}
262	
263	/**
264	 * Pack-size hint for display under the on-hand count.
265	 * Returns e.g. "× 5 kg" or just "kg" for pack_size=1.
266	 */
267	export function packSizeHint(
268	  packSize: number | null | undefined,
269	  unit: string | null | undefined,
270	): string {
271	  const ps = (packSize ?? 1) > 0 ? (packSize ?? 1) : 1;
272	  const def = resolveUnit(unit);
273	
274	  if (ps <= 1) return def.symbol;
275	  return `× ${formatNum(ps)} ${def.symbol}`;
276	}
277	
278	/**
279	 * Label for the "pack" chip in the dispense toggle.
280	 * e.g. "pack (5 kg)" or "pack (3 bars)"
281	 */
282	export function packChipLabel(
283	  packSize: number | null | undefined,
284	  unit: string | null | undefined,
285	): string {
286	  const ps = (packSize ?? 1) > 0 ? (packSize ?? 1) : 1;
287	  const def = resolveUnit(unit);
288	  return `pack (${formatNum(ps)} ${def.symbol})`;
289	}
290	
291	/**
292	 * Label for the "unit" chip in the dispense toggle.
293	 * e.g. "litres" or "bars"
294	 */
295	export function unitChipLabel(
296	  unit: string | null | undefined,
297	): string {
298	  const def = resolveUnit(unit);
299	  return def.displayName;
300	}
