19	} from '../../../design';
20	import { getSession } from '../../../auth/session';
21	import { correctStockLocal, findStock, getNearestExpiry, StockRow } from '../../../db/stock';
22	import { listLots, replaceLotsLocal } from '../../../db/lots';
23	import { enqueue } from '../../../db/outbox';
24	import { useT } from '../../../i18n';
25	import { useTheme } from '../../../theme';
26	import { RootStackParamList } from '../../../navigation/types';
