28	import { flushOnce } from '../../../sync/syncService';
29	import { haptic } from '../../../utils/haptics';
30	import { useKeyboardHeight } from '../../../hooks/useKeyboardHeight';
31	import { BatchEditor, Batch } from '../components/BatchEditor';
32	import { formatExpiry } from '../../../utils/expiry';
33	import { formatOnHand, resolveUnit } from '../../../units';
34	
35	type Props = NativeStackScreenProps<RootStackParamList, 'EditStock'>;
36	
37	/** Earliest non-null ISO date out of a list of batches. */
38	function earliestExpiry(batches: Batch[]): string | null {
39	  const sorted = batches
40	    .map((b) => b.expiry)
41	    .filter((e): e is string => !!e)
42	    .sort();
43	  return sorted[0] ?? null;
44	}
45	
46	/**
47	 * verifying  — JIT fetch in flight; save disabled.
48	 * ok         — server agrees with what we opened the screen with.
49	 * absent     — server has no row for this barcode (treat as ok — local
50	 *              view is the only truth; the correction will create it).
51	 * conflict   — server's on_hand or nearest_expiry differs from local;
52	 *              show prompt before letting user save.
53	 * offline    — fetch failed because network down; save disabled.
54	 * error      — fetch failed otherwise; save disabled.
55	 */
56	type VerifyStatus = 'verifying' | 'ok' | 'absent' | 'conflict' | 'offline' | 'error';
57	
58	function isOfflineError(err: unknown): boolean {
59	  const msg = err instanceof Error ? err.message : String(err);
60	  return (
61	    msg.includes('Network request failed') ||
62	    msg.includes('TypeError: Network') ||
63	    msg.includes('Unable to resolve host') ||
64	    msg === 'JIT timeout'
65	  );
66	}
67	
68	export function EditStockScreen({ route, navigation }: Props) {
69	  const t = useT();
70	  const { palette } = useTheme();
71	  const kbHeight = useKeyboardHeight();
72	  const { barcode } = route.params;
73	
74	  const [row, setRow] = useState<StockRow | null>(null);
75	  const [originalQty, setOriginalQty] = useState<number>(0);
76	  const [originalExpiry, setOriginalExpiry] = useState<string | null>(null);
77	  const [originalBatches, setOriginalBatches] = useState<Batch[]>([]);
78	  const [batches, setBatches] = useState<Batch[]>([]);
79	
80	  const [saving, setSaving] = useState(false);
81	
82	  // JIT verification — fetch the server's authoritative on_hand +
83	  // nearest_expiry the moment the screen opens, in parallel with the
84	  // local read. If the server differs, we surface a "Stock has changed"
85	  // prompt before letting the user save. If the fetch fails (timeout /
86	  // offline / 5xx), we block the save entirely — corrections must be
87	  // committed against verified state per the cache-freshness plan.
88	  const [verifyStatus, setVerifyStatus] = useState<VerifyStatus>('verifying');
89	  const [serverQty, setServerQty] = useState<number | null>(null);
90	  const [serverExpiry, setServerExpiry] = useState<string | null>(null);
91	
92	  useEffect(() => {
93	    let cancelled = false;
94	    (async () => {
95	      const r = await findStock(barcode);
96	      const exp = await getNearestExpiry(barcode);
97	      const lots = await listLots(barcode);
98	      if (cancelled) return;
99	      if (!r) return;
100	      setRow(r);
101	      setOriginalQty(r.on_hand);
102	      setOriginalExpiry(exp);
103	      // Seed batches from local lots. If lots are empty (legacy row from
104	      // before the lots migration, or fresh barcode), synthesise one
105	      // batch carrying the entire on_hand at the cached nearest_expiry.
106	      const seed: Batch[] = lots.length > 0
107	        ? lots.map((l) => ({ expiry: l.expiry_date, qty: Number(l.qty) }))
108	        : [{ expiry: exp, qty: r.on_hand || 1 }];
109	      setOriginalBatches(seed);
110	      setBatches(seed);
111	    })();
112	    return () => { cancelled = true; };
113	  }, [barcode]);
114	
115	  // Fire the JIT fetch independently of the local read so neither
116	  // blocks the other. The 3 s timeout matches CatalogPickerScreen.
117	  useEffect(() => {
118	    let cancelled = false;
119	    const controller = new AbortController();
120	    const t = setTimeout(() => controller.abort(), 3000);
121	    (async () => {
122	      try {
123	        const remote = await api.fetch.stockOne(barcode);
124	        if (cancelled) return;
125	        const remoteQty = Number(remote.on_hand);
126	        const remoteExpiry = remote.nearest_expiry ?? null;
127	        setServerQty(remoteQty);
128	        setServerExpiry(remoteExpiry);
129	        setVerifyStatus('ok'); // narrowed to 'conflict' below once we know local values
130	      } catch (err) {
131	        if (cancelled) return;
132	        // 404 = no stock row on server; treat as authoritative "absent"
133	        // — the correction will create it. Same UX as a clean ok.
134	        if (err instanceof ApiError && err.status === 404) {
135	          setVerifyStatus('absent');
136	          return;
137	        }
138	        // 401 is handled centrally; clear navigates to Login.
139	        if (err instanceof ApiError && err.status === 401) return;
140	        setVerifyStatus(isOfflineError(err) ? 'offline' : 'error');
141	      } finally {
142	        clearTimeout(t);
143	      }
144	    })();
145	    return () => { cancelled = true; clearTimeout(t); controller.abort(); };
146	  }, [barcode]);
147	
148	  // Once both local and server have settled, classify ok-vs-conflict.
149	  // Conflict iff server differs from what the user is about to edit.
150	  // We use originalQty/originalExpiry as the "what the user opened
151	  // with" reference — those don't change unless the user explicitly
152	  // accepts the new server values.
153	  useEffect(() => {
154	    if (verifyStatus !== 'ok' || row === null || serverQty === null) return;
155	    const qtyDiffers = Math.abs(serverQty - originalQty) > 1e-9;
156	    const expiryDiffers = (serverExpiry ?? null) !== (originalExpiry ?? null);
157	    if (qtyDiffers || expiryDiffers) setVerifyStatus('conflict');
158	  }, [verifyStatus, row, serverQty, serverExpiry, originalQty, originalExpiry]);
159	
160	  /** Total qty across all batches — replaces the old single qty stepper. */
161	  const qty = useMemo(() => batches.reduce((s, b) => s + (b.qty || 0), 0), [batches]);
162	
163	  /** Whatever ends up as the locally-tracked "nearest" expiry. */
164	  const localNearestExpiry = useMemo(() => earliestExpiry(batches), [batches]);
165	
166	  /** True iff batches differ from what was loaded — qty or per-batch
167	   *  expiry. Counts re-orderings as no change. */
168	  const changed = useMemo(() => {
169	    if (!row) return false;
170	    const a = [...batches]
171	      .map((b) => `${b.expiry ?? ''}@${b.qty}`)
172	      .sort()
173	      .join('|');
174	    const b = [...originalBatches]
175	      .map((b) => `${b.expiry ?? ''}@${b.qty}`)
176	      .sort()
177	      .join('|');
178	    return a !== b;
179	  }, [row, batches, originalBatches]);
180	  /**
181	   * User accepted the server's view. Rebase originalQty / originalExpiry
182	   * and also replace what's in the steppers / date picker so the
183	   * "current count" line and the inputs match. The audit record's
184	   * old_qty / old_expiry will now reflect the actual transition.
185	   */
186	  const acceptServerView = () => {
187	    if (serverQty === null) return;
188	    haptic.tap();
189	    setOriginalQty(serverQty);
190	    setOriginalExpiry(serverExpiry ?? null);
191	    // We don't have the server's per-batch breakdown in the conflict
192	    // banner state — collapse into a single batch carrying the
193	    // server's nearest expiry. The guard can split it again after.
194	    const seed: Batch[] = [{ expiry: serverExpiry ?? null, qty: serverQty }];
195	    setOriginalBatches(seed);
196	    setBatches(seed);
197	    setVerifyStatus('ok');
198	  };
199	
200	  /**
201	   * User chose to keep their edit. We still rebase originalQty /
202	   * originalExpiry to the SERVER's truth so the audit record reflects
203	   * "server was N, guard set it to M" — not "guard thought it was N
204	   * (stale), set it to M". Steppers untouched.
205	   */
206	  const keepUserEdit = () => {
207	    if (serverQty === null) return;
208	    haptic.tap();
209	    setOriginalQty(serverQty);
210	    setOriginalExpiry(serverExpiry ?? null);
211	    setVerifyStatus('ok');
212	  };
213	
214	  const submit = async () => {
215	    if (!row || !changed) return;
216	    const session = getSession();
217	    setSaving(true);
218	    try {
219	      // Coerce tri-state expiry (undefined = unset) → null for persistence.
220	      const cleanBatches = batches
221	        .filter((b) => b.qty > 0)
222	        .map((b) => ({ ...b, expiry: b.expiry ?? null }));
223	      // Optimistic local writes: stock cache + lots mirror.
224	      await correctStockLocal(barcode, qty, localNearestExpiry);
225	      await replaceLotsLocal(
226	        barcode,
227	        cleanBatches.map((b) => ({ expiry_date: b.expiry, qty: b.qty })),
228	      );
229	      await enqueue('stock_correction', {
230	        id: `crn_${nanoid(12)}`,
231	        barcode,
232	        product_name: row.name,
233	        old_qty: originalQty,
234	        new_qty: qty,
235	        old_expiry: originalExpiry,
236	        // New canonical shape: per-batch breakdown. Server's correction
237	        // route prefers `lots` over the legacy `new_expiry` /
238	        // `new_expiries` fields.
239	        lots: cleanBatches.map((b) => ({ expiry_date: b.expiry, qty: b.qty })),
240	        // Legacy fields kept for backward compatibility with older
241	        // server builds and dashboard audit views.
242	        new_expiry: cleanBatches.length === 1 ? cleanBatches[0].expiry : localNearestExpiry,
243	        new_expiries: null,
244	        performed_by: session?.guardId ?? null,
245	        performed_by_name: session?.guardName ?? null,
246	        corrected_at: Date.now(),
247	      });
248	      // Await the flush so the StockScreen's focus refresh sees the
249	      // server-acknowledged value, not stale read-back data. Without
250	      // this, the GET races the POST and replaceStockFromRemote
251	      // overwrites the local optimistic write.
252	      await flushOnce().catch(() => {});
253	      haptic.success();
254	      navigation.goBack();
255	    } finally {
256	      setSaving(false);
257	    }
258	  };
259	
260	  if (!row) {
261	    return (
262	      <View style={[styles.safe, { backgroundColor: palette.background }]}>
263	        <AppBar title={t('editStock')} onBack={() => navigation.goBack()} />
264	      </View>
265	    );
266	  }
267	
268	  return (
269	    <KeyboardAvoidingView
270	      behavior={Platform.OS === 'ios' ? 'height' : undefined}
271	      style={{ flex: 1 }}
272	    >
273	      <View style={[styles.safe, { backgroundColor: palette.background }]}>
274	        <AppBar title={t('editStock')} subtitle={t('editStockSub')} onBack={() => navigation.goBack()} />
275	
276	        <ScrollView
277	          contentContainerStyle={[styles.content, { paddingBottom: spacing.xxxl + kbHeight }]}
278	          keyboardShouldPersistTaps="handled"
279	        >
280	          {/* JIT verification status banners.
281	              - verifying: tiny inline indicator at top
282	              - conflict: amber banner with "Use new count" / "Keep my edit"
283	              - offline/error: red banner, save disabled, can retry */}
284	          {verifyStatus === 'verifying' && (
285	            <View style={[styles.statusBanner, { borderColor: palette.outlineVariant }]}>
286	              <ActivityIndicator color={palette.primary} size="small" />
287	              <Text variant="bodyMedium" color={palette.onSurfaceVariant} style={{ marginLeft: spacing.sm }}>
288	                {t('verifying')}
289	              </Text>
290	            </View>
291	          )}
292	          {verifyStatus === 'conflict' && serverQty !== null && (
293	            <View
294	              style={[
295	                styles.statusBanner,
296	                {
297	                  borderColor: '#F9A825',
298	                  backgroundColor: 'rgba(249, 168, 37, 0.10)',
299	                  flexDirection: 'column',
300	                  alignItems: 'stretch',
301	                  gap: spacing.sm,
302	                },
303	              ]}
304	            >
305	              <Text variant="titleMedium" color={palette.onSurface}>
306	                {t('stockUpdatedTitle')}
307	              </Text>
308	              <Text variant="bodyMedium" color={palette.onSurfaceVariant}>
309	                {t('stockUpdatedBody')}
310	              </Text>
311	              <Text variant="bodyMedium" color={palette.onSurface}>
312	                {formatOnHand(originalQty, row?.pack_size, row?.unit)} → {formatOnHand(serverQty, row?.pack_size, row?.unit)}
313	                {serverExpiry && serverExpiry !== originalExpiry
314	                  ? ` · ${formatExpiry(serverExpiry)}`
315	                  : ''}
316	              </Text>
317	              <View style={{ flexDirection: 'row', gap: spacing.sm }}>
318	                <Button label={t('useNewCount')} variant="filled" size="md" onPress={acceptServerView} />
319	                <Button label={t('keepMyEdit')} variant="tonal" size="md" onPress={keepUserEdit} />
320	              </View>
321	            </View>
322	          )}
323	          {(verifyStatus === 'offline' || verifyStatus === 'error') && (
324	            <View
325	              style={[
326	                styles.statusBanner,
327	                { borderColor: palette.error, backgroundColor: palette.errorContainer ?? 'transparent' },
328	              ]}
329	            >
330	              <Text variant="bodyMedium" color={palette.error} style={{ flex: 1 }}>
331	                {t('couldntVerify')}
332	              </Text>
333	            </View>
334	          )}
335	
336	          <Card tone="elevated" padding="xl">
337	            <Text variant="labelLarge" color={palette.onSurfaceVariant}>
338	              {t('product').toUpperCase()}
339	            </Text>
340	            <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'flex-end', marginTop: spacing.xs, gap: spacing.md }}>
341	              <Text variant="headlineSmall" style={{ flex: 1 }}>{row.name}</Text>
342	            </View>
343	            <Text variant="bodyMedium" color={palette.onSurfaceVariant} style={{ marginTop: spacing.md }}>
344	              {t('currentCount')}: {formatOnHand(originalQty, row.pack_size, row.unit)}
345	            </Text>
346	          </Card>
347	
348	          <BatchEditor
349	            batches={batches}
350	            onChange={setBatches}
351	            unit={row.unit ?? null}
352	            packSize={row.pack_size ?? null}
353	            decimal={resolveUnit(row.unit).nature === 'continuous'}
354	          />
355	        </ScrollView>
356	
357	        <View style={[styles.footer, { backgroundColor: palette.surface, borderTopColor: palette.outlineVariant }]}>
358	          {/* Save is gated by verification: cannot commit a correction
359	              while we're still verifying, in conflict (user must
360	              resolve via the banner), or while verification failed
361	              (offline / error — user retries by going back and re-
362	              opening once network returns). */}
363	          <Button
364	            label={changed ? t('saveChanges') : t('noChanges')}
365	            onPress={submit}
366	            loading={saving}
367	            disabled={
368	              !changed ||
369	              verifyStatus === 'verifying' ||
370	              verifyStatus === 'conflict' ||
371	              verifyStatus === 'offline' ||
372	              verifyStatus === 'error'
373	            }
374	            size="lg"
375	            fullWidth
376	            leadingIcon={<Check size={22} color={palette.onPrimary} strokeWidth={2.4} />}
377	          />
378	          <Button
379	            label={t('cancel')}
380	            variant="text"
381	            onPress={() => navigation.goBack()}
382	            style={{ marginTop: spacing.sm }}
383	          />
384	        </View>
385	      </View>
386	    </KeyboardAvoidingView>
387	  );
388	}
389	
390	const styles = StyleSheet.create({
391	  safe: { flex: 1 },
392	  content: { padding: spacing.xl, gap: spacing.xl },
393	  footer: {
394	    padding: spacing.xl,
395	    borderTopWidth: 1,
396	  },
397	  statusBanner: {
398	    flexDirection: 'row',
399	    alignItems: 'center',
400	    padding: spacing.md,
401	    borderRadius: 8,
402	    borderWidth: 1,
403	  },
404	});
