1	import { CalendarDays, CalendarOff, Trash2, X } from 'lucide-react-native';
2	import React, { useMemo, useState } from 'react';
3	import { Pressable, StyleSheet, TextInput, View } from 'react-native';
4	import { CompactStepper, radius, spacing, Text } from '../../../design';
5	import { useT } from '../../../i18n';
6	import { useTheme } from '../../../theme';
7	import { haptic } from '../../../utils/haptics';
8	import {
9	  compareExpiryAsc,
10	  expiryUrgency,
11	  formatExpiry,
12	  relativeExpiry,
13	  urgencyColors,
14	} from '../../../utils/expiry';
15	import { DatePickerModal } from './DatePickerModal';
16	
17	export type Batch = {
18	  /** Tri-state:
19	   *    string    = ISO YYYY-MM-DD date
20	   *    null      = guard explicitly chose "no expiry"
21	   *    undefined = unset; both chips ("Pick expiry" / "No expiry") shown
22	   *  Downstream code that just needs "is there an expiry date" can keep
23	   *  using a truthy check; submit paths should coerce undefined → null. */
24	  expiry: string | null | undefined;
25	  qty: number;
26	};
27	
28	function toISO(d: Date): string {
29	  return d.toISOString().split('T')[0];
30	}
31	
32	/**
33	 * Edits a list of per-expiry batches for receiving / corrections. Each
34	 * row carries `{qty, expiry}`. Expiry has one combined control:
35	 *   - Unset → two chips: "Pick date" (opens picker) and "No expiry".
36	 *   - Set   → a single urgency-colored chip (date · relative time · ×).
37	 *
38	 * Batches sort by expiry ascending (earliest first, no-expiry last) at
39	 * render time, so the visual order matches FEFO consumption. The caller's
40	 * source-of-truth list also gets the sort whenever a date is picked.
41	 */
42	export function BatchEditor({
43	  batches,
44	  onChange,
45	  minDate,
46	  unit,
47	  packSize,
48	  decimal = false,
49	}: {
50	  batches: Batch[];
51	  onChange: (next: Batch[]) => void;
52	  minDate?: Date;
53	  /** Base unit string, e.g. "g". */
54	  unit?: string | null;
55	  /** Pack size — needed to render "2 × 500 g" (pack mode) vs raw unit
56	   *  (divisible). When omitted, falls back to bare qty + unit. */
57	  packSize?: number | null;
58	  decimal?: boolean;
59	}) {
60	  const t = useT();
61	  const { palette } = useTheme();
62	  const [editingIdx, setEditingIdx] = useState<number | null>(null);
63	  const divisible = decimal;
64	
65	  // Auto-sort by expiry (earliest first, null last). Caller still owns
66	  // the array; we just present it FEFO-ordered.
67	  const sortedBatches = useMemo(
68	    () =>
69	      batches
70	        .map((b, originalIdx) => ({ b, originalIdx }))
71	        .sort((a, z) => compareExpiryAsc(a.b.expiry, z.b.expiry)),
72	    [batches],
73	  );
74	
75	  const total = batches.reduce((s, b) => s + (b.qty || 0), 0);
76	  const ps = packSize ?? null;
77	  const usePackForm = !divisible && ps != null && ps !== 1;
78	  const totalDisplay = divisible
79	    ? (Math.round(total * 1000) / 1000).toString()
80	    : String(total);
81	  const totalSuffix = usePackForm
82	    ? ` × ${ps}${unit ? ` ${unit}` : ''}`
83	    : unit ? ` ${unit}` : '';
84	
85	  const updateByOriginal = (originalIdx: number, next: Partial<Batch>) => {
86	    const merged = batches.map((b, idx) => (idx === originalIdx ? { ...b, ...next } : b));
87	    onChange(merged);
88	  };
89	  const removeByOriginal = (originalIdx: number) => {
90	    haptic.tap();
91	    onChange(batches.filter((_, idx) => idx !== originalIdx));
92	  };
93	  const add = () => {
94	    haptic.tap();
95	    // undefined = unset; both chips visible. Forces a deliberate choice
96	    // instead of silently defaulting to "no expiry".
97	    onChange([...batches, { qty: divisible ? 0 : 1, expiry: undefined }]);
98	  };
99	
100	  const labelForRowNumber = (visualIdx: number) => `#${visualIdx + 1}`;
101	
102	  return (
103	    <View style={{ gap: spacing.sm }}>
104	      <View
105	        style={{
106	          flexDirection: 'row',
107	          justifyContent: 'space-between',
108	          alignItems: 'baseline',
109	        }}
110	      >
111	        <Text variant="labelLarge" color={palette.onSurfaceVariant}>
112	          {t('batches').toUpperCase()}
113	        </Text>
114	        <Text variant="bodyMedium" color={palette.onSurfaceVariant}>
115	          {t('totalLabel')}: {totalDisplay}{totalSuffix}
116	        </Text>
117	      </View>
118	
119	      {sortedBatches.map(({ b, originalIdx }, visualIdx) => {
120	        const urgency = expiryUrgency(b.expiry);
121	        const colors = urgencyColors(urgency, palette);
122	        const canRemove = batches.length > 1;
123	        return (
124	          <View
125	            key={originalIdx}
126	            style={[
127	              styles.card,
128	              {
129	                backgroundColor: palette.surfaceContainerLowest,
130	                borderColor: palette.outlineVariant,
131	              },
132	            ]}
133	          >
134	            {/* ─── Left rail: batch number, centered ─── */}
135	            <View
136	              style={[
137	                styles.rail,
138	                styles.leftRail,
139	                {
140	                  backgroundColor: palette.surfaceContainerLow,
141	                  borderRightColor: palette.outlineVariant,
142	                },
143	              ]}
144	            >
145	              <Text
146	                variant="titleMedium"
147	                color={palette.onSurfaceVariant}
148	                style={{ fontWeight: '700' }}
149	              >
150	                {visualIdx + 1}
151	              </Text>
152	            </View>
153	
154	            {/* ─── Middle: the actual fields ─── */}
155	            <View style={styles.middle}>
156	              {/* Qty section */}
157	              <View style={{ gap: spacing.xs }}>
158	                <Text variant="labelMedium" color={palette.onSurfaceVariant} style={styles.sectionLabel}>
159	                  {t('howMany').toUpperCase()}
160	                </Text>
161	                {divisible ? (
162	                  <View style={{ flexDirection: 'row', alignItems: 'center', gap: spacing.xs }}>
163	                    <TextInput
164	                      value={b.qty === 0 ? '' : String(b.qty)}
165	                      onChangeText={(txt) => {
166	                        const cleaned = txt.replace(/[^0-9.]/g, '');
167	                        const n = cleaned === '' || cleaned === '.' ? 0 : Number(cleaned);
168	                        updateByOriginal(originalIdx, { qty: Number.isFinite(n) ? n : 0 });
169	                      }}
170	                      keyboardType="decimal-pad"
171	                      placeholder="0"
172	                      placeholderTextColor={palette.onSurfaceVariant}
173	                      style={[
174	                        styles.decimalInput,
175	                        {
176	                          borderColor: palette.outline,
177	                          color: palette.onSurface,
178	                          backgroundColor: palette.surface,
179	                        },
180	                      ]}
181	                    />
182	                    {unit ? (
183	                      <Text variant="bodyMedium" color={palette.onSurfaceVariant}>
184	                        {unit}
185	                      </Text>
186	                    ) : null}
187	                  </View>
188	                ) : (
189	                  <CompactStepper
190	                    value={b.qty}
191	                    onChange={(v) => updateByOriginal(originalIdx, { qty: v })}
192	                    min={1}
193	                  />
194	                )}
195	              </View>
196	
197	              {/* Expiry section */}
198	              <View style={{ gap: spacing.xs }}>
199	                <Text variant="labelMedium" color={palette.onSurfaceVariant} style={styles.sectionLabel}>
200	                  {t('expires').toUpperCase()}
201	                </Text>
202	              {/* Expiry row — three visual states:
203	                  • undefined → two chips, user must pick
204	                  • null      → "No expiry" confirmed chip with ×
205	                  • string    → date chip with × (urgency-colored) */}
206	              {b.expiry === undefined ? (
207	                <View style={styles.chipRow}>
208	                  <Pressable
209	                    onPress={() => {
210	                      haptic.tap();
211	                      setEditingIdx(originalIdx);
212	                    }}
213	                    style={[
214	                      styles.chip,
215	                      {
216	                        borderColor: palette.primary,
217	                        backgroundColor: palette.surfaceContainerLow,
218	                      },
219	                    ]}
220	                  >
221	                    <CalendarDays size={16} color={palette.primary} strokeWidth={2.2} />
222	                    <Text
223	                      variant="labelLarge"
224	                      color={palette.primary}
225	                      style={{ marginLeft: spacing.xs }}
226	                    >
227	                      {t('pickExpiry')}
228	                    </Text>
229	                  </Pressable>
230	
231	                  <Pressable
232	                    onPress={() => {
233	                      haptic.tap();
234	                      updateByOriginal(originalIdx, { expiry: null });
235	                    }}
236	                    style={[
237	                      styles.chip,
238	                      {
239	                        borderColor: palette.outline,
240	                        backgroundColor: 'transparent',
241	                      },
242	                    ]}
243	                  >
244	                    <CalendarOff size={16} color={palette.onSurfaceVariant} strokeWidth={2.2} />
245	                    <Text
246	                      variant="labelLarge"
247	                      color={palette.onSurfaceVariant}
248	                      style={{ marginLeft: spacing.xs }}
249	                    >
250	                      {t('noExpiry')}
251	                    </Text>
252	                  </Pressable>
253	                </View>
254	              ) : b.expiry === null ? (
255	                <Pressable
256	                  onPress={() => {
257	                    haptic.tap();
258	                    setEditingIdx(originalIdx);
259	                  }}
260	                  style={[
261	                    styles.expiryChip,
262	                    {
263	                      borderColor: palette.outline,
264	                      backgroundColor: palette.surfaceContainerLow,
265	                    },
266	                  ]}
267	                >
268	                  <CalendarOff size={16} color={palette.onSurfaceVariant} strokeWidth={2.2} />
269	                  <View style={{ marginLeft: spacing.sm, flex: 1 }}>
270	                    <Text variant="titleMedium" color={palette.onSurface}>
271	                      {t('noExpiry')}
272	                    </Text>
273	                    <Text variant="labelMedium" color={palette.onSurfaceVariant}>
274	                      {t('tapToPickDate')}
275	                    </Text>
276	                  </View>
277	                  <Pressable
278	                    onPress={(e) => {
279	                      e.stopPropagation();
280	                      haptic.tap();
281	                      // Back to unset — re-shows both chips.
282	                      updateByOriginal(originalIdx, { expiry: undefined });
283	                    }}
284	                    hitSlop={10}
285	                    style={styles.clearBtn}
286	                  >
287	                    <X size={16} color={palette.onSurfaceVariant} strokeWidth={2.2} />
288	                  </Pressable>
289	                </Pressable>
290	              ) : (
291	                <Pressable
292	                  onPress={() => setEditingIdx(originalIdx)}
293	                  style={[
294	                    styles.expiryChip,
295	                    {
296	                      borderColor: colors.border,
297	                      backgroundColor: colors.bg,
298	                    },
299	                  ]}
300	                >
301	                  <CalendarDays size={16} color={colors.fg} strokeWidth={2.2} />
302	                  <View style={{ marginLeft: spacing.sm, flex: 1 }}>
303	                    <Text variant="titleMedium" color={colors.fg}>
304	                      {formatExpiry(b.expiry)}
305	                    </Text>
306	                    {relativeExpiry(b.expiry, t) ? (
307	                      <Text variant="labelMedium" color={colors.fg} style={{ opacity: 0.85 }}>
308	                        {relativeExpiry(b.expiry, t)}
309	                      </Text>
310	                    ) : null}
311	                  </View>
312	                  <Pressable
313	                    onPress={(e) => {
314	                      e.stopPropagation();
315	                      haptic.tap();
316	                      // Clearing a picked date drops back to unset.
317	                      updateByOriginal(originalIdx, { expiry: undefined });
318	                    }}
319	                    hitSlop={10}
320	                    style={styles.clearBtn}
321	                  >
322	                    <X size={16} color={colors.fg} strokeWidth={2.2} />
323	                  </Pressable>
324	                </Pressable>
325	              )}
326	              </View>
327	            </View>
328	
329	            {/* ─── Right rail: delete button, centered. Only when more
330	                 than one batch exists (can't delete the last one). ─── */}
331	            {canRemove ? (
332	              <Pressable
333	                onPress={() => removeByOriginal(originalIdx)}
334	                android_ripple={{ color: palette.outlineVariant, borderless: false }}
335	                style={[
336	                  styles.rail,
337	                  styles.rightRail,
338	                  {
339	                    backgroundColor: palette.surfaceContainerLow,
340	                    borderLeftColor: palette.outlineVariant,
341	                  },
342	                ]}
343	                hitSlop={6}
344	              >
345	                <Trash2 size={20} color={palette.error} strokeWidth={2.2} />
346	              </Pressable>
347	            ) : (
348	              // Keep the layout symmetrical even when the trash isn't shown,
349	              // so a single batch doesn't look unbalanced — render a muted
350	              // rail with no glyph.
351	              <View
352	                style={[
353	                  styles.rail,
