1	import { NativeStackScreenProps } from '@react-navigation/native-stack';
2	import { Check } from 'lucide-react-native';
3	import { nanoid } from 'nanoid/non-secure';
4	import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
5	import {
6	  ActivityIndicator,
7	  FlatList,
8	  KeyboardAvoidingView,
9	  Platform,
10	  RefreshControl,
11	  ScrollView,
12	  StyleSheet,
13	  TextInput,
14	  View,
15	} from 'react-native';
16	import {
17	  AppBar,
18	  Button,
19	  Card,
20	  Chip,
21	  UnitAwareStepper,
22	  radius,
23	  Skeleton,
24	  spacing,
25	  Text,
26	} from '../../../design';
27	import type { DispenseMode } from '../../../design';
28	import {
29	  baseToPack,
30	  packToBase,
31	  canSubdivide,
32	  formatOnHand,
33	  formatOnHandShort,
34	  resolveUnit,
35	} from '../../../units';
36	import { enqueue } from '../../../db/outbox';
37	import { adjustOnHand, findStock, getNearestExpiry, listStock, replaceStockFromRemote, StockRow, statusFor } from '../../../db/stock';
38	import { decrementLotsLocal, listLots, pruneLotsToBarcodes, replaceLotsLocal } from '../../../db/lots';
39	import { LotAllocation, LotPicker, suggestFEFO } from '../components/LotPicker';
40	import { getSession } from '../../../auth/session';
41	import { useT } from '../../../i18n';
42	import { StringKey } from '../../../i18n/strings';
43	import { RootStackParamList } from '../../../navigation/types';
44	import { api, ApiError } from '../../../sync/api';
45	import { flushOnce } from '../../../sync/syncService';
46	import { invalidateRefetchThrottle, refetchThrottled } from '../../../sync/refetch';
47	import { haptic } from '../../../utils/haptics';
48	import { useKeyboardHeight } from '../../../hooks/useKeyboardHeight';
49	import { FilterDropdown, FilterOption } from '../components/FilterDropdown';
50	import { PackVisual } from '../components/PackVisual';
51	import { useTheme } from '../../../theme';
52	
53	type Props = NativeStackScreenProps<RootStackParamList, 'Dispense'>;
54	
55	// `value` is the canonical English string recorded on the dispense; only
56	// the displayed label is translated, so reporting/grouping stays stable
57	// regardless of the guard's chosen language.
58	const REASONS: { value: string; labelKey: StringKey }[] = [
59	  { value: 'Office use', labelKey: 'reasonOfficeUse' },
60	  { value: 'Pantry', labelKey: 'reasonPantry' },
61	  { value: 'Cleaning', labelKey: 'reasonCleaning' },
62	  { value: 'Maintenance', labelKey: 'reasonMaintenance' },
63	  { value: 'Other', labelKey: 'reasonOther' },
64	];
65	
66	// Stable keys drive the filter logic; labels are resolved per-render.
67	const STATUS_OPTIONS: { key: string; labelKey: StringKey }[] = [
68	  { key: 'All', labelKey: 'statusAll' },
69	  { key: 'In Stock', labelKey: 'statusInStock' },
70	  { key: 'Low', labelKey: 'statusLow' },
71	  { key: 'Out', labelKey: 'statusOut' },
72	];
73	
74	type VerifyStatus = 'verifying' | 'ok' | 'absent' | 'offline' | 'error';
75	
76	function isOfflineError(err: unknown): boolean {
77	  const msg = err instanceof Error ? err.message : String(err);
78	  return (
79	    msg.includes('Network request failed') ||
80	    msg.includes('TypeError: Network') ||
81	    msg.includes('Unable to resolve host')
82	  );
83	}
84	
85	/** Subtle background tint per stock health */
86	function cardBg(row: StockRow): string {
87	  const s = statusFor(row);
88	  if (s === 'out') return 'rgba(229, 57, 53, 0.07)';
89	  if (s === 'low') return 'rgba(249, 168, 37, 0.07)';
90	  if (row.on_hand >= row.threshold * 2) return 'rgba(67, 160, 71, 0.06)';
91	  return 'rgba(129, 199, 132, 0.06)';
92	}
93	
94	/** Count text color per stock health */
95	function countColor(row: StockRow): string {
96	  const s = statusFor(row);
97	  if (s === 'out') return '#E53935';
98	  if (s === 'low') return '#F9A825';
99	  if (row.on_hand >= row.threshold * 2) return '#43A047';
100	  return '#66BB6A';
101	}
102	
103	/**
104	 * The value a fresh dispense should open on. Starts at ONE unit of the
105	 * product's natural denomination — 1 pack for whole-pack goods, 1 base
106	 * unit (e.g. 1 kg) for divisible ones — capped at what's actually in
107	 * stock. Opening on the full available count read to guards as "take
108	 * everything"; dialing UP from a small amount is how dispensing works.
109	 * Returns the qty in packs (the denomination the lot system stores) plus
110	 * the mode the stepper should open in.
111	 */
112	function startingDispense(
113	  available: number,
114	  packSize: number | null | undefined,
115	  unit: string | null | undefined,
116	): { mode: DispenseMode; qty: number } {
117	  const ps = (packSize ?? 1) > 0 ? (packSize ?? 1) : 1;
118	  const divisible = canSubdivide(packSize, unit) && resolveUnit(unit).nature === 'continuous';
119	  const mode: DispenseMode = divisible ? 'unit' : 'pack';
120	  const oneUnitInPacks = mode === 'unit' ? 1 / ps : 1;
121	  return { mode, qty: Math.max(0, Math.min(available, oneUnitInPacks)) };
122	}
123	
124	export function DispenseScreen({ route, navigation }: Props) {
125	  const t = useT();
126	  const { palette } = useTheme();
127	  const kbHeight = useKeyboardHeight();
128	  const initialBarcode = route.params?.barcode;
129	  const [selected, setSelected] = useState<StockRow | null>(null);
130	  const [all, setAll] = useState<StockRow[]>([]);
131	  const [query, setQuery] = useState('');
132	  const [category, setCategory] = useState('All');
133	  const [statusFilter, setStatusFilter] = useState('All');
134	  const [qty, setQty] = useState(1);
135	  // Whether the guard is picking in 'pack' (whole/fractional packs)
136	  // or 'unit' (base units like kg, litres, bars). Driven by the
137	  // UnitAwareStepper chip toggle.
138	  const [dispenseMode, setDispenseMode] = useState<DispenseMode>('pack');
139	  const [reason, setReason] = useState(REASONS[0].value);
