701	              </View>
702	
703	              {/* Per-lot picker. Only worth showing when there are 2+ lots —
704	                  for the common single-lot case the big stepper above is the
705	                  whole story. FEFO is highlighted as "← suggested"; guard
706	                  can override per-row. */}
707	              {availability.length > 1 && (
708	                <LotPicker
709	                  lots={allocation}
710	                  onChange={onAllocationChange}
711	                  desiredQty={qty}
712	                  unit={selected.unit ?? null}
713	                  packSize={selected.pack_size ?? null}
714	                  decimal={resolveUnit(selected.unit).nature === 'continuous'}
715	                />
716	              )}
717	            </>
718	          )}
719	
720	          <View>
721	            <Text variant="labelLarge" color={palette.onSurfaceVariant} style={{ marginBottom: spacing.sm }}>
722	              {t('reason').toUpperCase()}
723	            </Text>
724	            <View style={styles.chipRow}>
725	              {REASONS.map((r) => (
726	                <Chip
727	                  key={r.value}
728	                  label={t(r.labelKey)}
729	                  selected={r.value === reason}
730	                  onPress={() => setReason(r.value)}
731	                />
732	              ))}
733	            </View>
734	          </View>
735	
736	          {/* Who took it: always the logged-in guard. No need for a
737	              text input; just surface their name so they know the
738	              record will be filed under them. */}
739	          <View style={{ marginTop: spacing.md }}>
740	            <Text variant="labelLarge" color={palette.onSurfaceVariant}>
741	              {t('whoTook').toUpperCase()}
742	            </Text>
743	            <Text variant="titleMedium" style={{ marginTop: spacing.xs }}>
744	              {getSession()?.guardName ?? '—'}
745	            </Text>
746	          </View>
747	        </ScrollView>
748	
749	        <View style={[styles.footer, { backgroundColor: palette.surface, borderTopColor: palette.outlineVariant }]}>
750	          {/* Confirm is blocked only while the live check is still running
751	              ('verifying') or when the server has no record of the item
752	              ('absent'). Offline / failed checks fall back to the saved
753	              count and are allowed (offline-first) — the write queues in
754	              the outbox and reconciles on sync. */}
755	          <Button
756	            label={t('confirm')}
757	            onPress={submit}
758	            loading={saving}
759	            disabled={verifyStatus === 'verifying' || verifyStatus === 'absent' || totalTaken <= 0}
760	            size="lg"
761	            fullWidth
762	            leadingIcon={<Check size={22} color={palette.onPrimary} strokeWidth={2.4} />}
763	          />
764	        </View>
765	      </KeyboardAvoidingView>
766	    </View>
767	  );
768	}
769	
770	const styles = StyleSheet.create({
771	  safe: { flex: 1 },
772	  search: { paddingHorizontal: spacing.xl, paddingTop: spacing.sm },
773	  filterRow: {
774	    flexDirection: 'row',
775	    gap: spacing.sm,
776	    paddingHorizontal: spacing.xl,
777	    paddingVertical: spacing.md,
778	  },
779	  searchInput: {
780	    borderRadius: radius.md,
781	    borderWidth: 1.5,
782	    paddingHorizontal: spacing.lg,
783	    minHeight: 52,
784	    fontSize: 17,
785	  },
786	  list: { padding: spacing.xl, paddingBottom: spacing.xxxl },
787	  pickerRow: { flexDirection: 'row', alignItems: 'center', gap: spacing.md },
788	  body: { flexGrow: 1, padding: spacing.xl, gap: spacing.xl },
789	  qtySection: { gap: spacing.lg },
790	  chipRow: { flexDirection: 'row', flexWrap: 'wrap', gap: spacing.sm },
791	  empty: { padding: spacing.xxl },
792	  footer: {
793	    padding: spacing.xl,
794	    borderTopWidth: 1,
795	  },
