109	
110	  if (lots.length === 0) {
111	    return (
112	      <View>
113	        <Text variant="bodyMedium" color={palette.onSurfaceVariant}>
114	          —
115	        </Text>
116	      </View>
117	    );
118	  }
119	
120	  return (
121	    <View style={{ gap: spacing.sm }}>
122	      {/* Header: title on the left, prominent "TAKEN / TOTAL" badge on the
123	          right. Badge turns primary when fully allocated so the user gets
124	          an unmissable visual cue that the picker is satisfied. */}
125	      <View style={styles.header}>
126	        <View style={{ flex: 1 }}>
127	          <Text variant="labelLarge" color={palette.onSurfaceVariant}>
128	            {t('pickFromBatch').toUpperCase()}
129	          </Text>
130	          {headerUnitHint ? (
131	            <Text variant="bodyMedium" color={palette.onSurfaceVariant} style={{ marginTop: 2 }}>
132	              1 = {headerUnitHint}
133	            </Text>
134	          ) : null}
135	        </View>
136	        <View
137	          style={[
138	            styles.headerBadge,
139	            {
140	              backgroundColor: complete
141	                ? palette.primary
142	                : palette.surfaceContainerHighest,
143	              borderColor: complete ? palette.primary : palette.outlineVariant,
144	            },
145	          ]}
146	        >
147	          <Text
148	            variant="headlineSmall"
149	            color={complete ? palette.onPrimary : palette.onSurface}
150	            style={{ fontWeight: '700' }}
151	          >
152	            {fmtNum(total)}
153	          </Text>
154	          <Text
155	            variant="bodyMedium"
156	            color={complete ? palette.onPrimary : palette.onSurfaceVariant}
157	          >
158	            {' / '}{fmtNum(grandTotal)}
159	          </Text>
160	        </View>
161	      </View>
162	
163	      {lots.map((lot, i) => {
164	        const isFefoSuggested = i === 0;
165	        const lotComplete = lot.take > 0 && lot.take === lot.available;
166	        return (
167	          <View
168	            key={`${lot.expiry ?? '__none__'}-${i}`}
169	            style={[
170	              styles.row,
171	              {
172	                backgroundColor: palette.surfaceContainerLowest,
173	                borderColor:
174	                  isFefoSuggested && lot.take > 0
175	                    ? palette.primary
176	                    : palette.outlineVariant,
177	                borderWidth: isFefoSuggested && lot.take > 0 ? 2 : 1,
178	              },
179	            ]}
180	          >
181	            <View style={{ flex: 1 }}>
182	              {(() => {
183	                const urgency = expiryUrgency(lot.expiry);
184	                const colors = urgencyColors(urgency, palette);
185	                const rel = relativeExpiry(lot.expiry, t);
186	                return (
187	                  <View style={{ flexDirection: 'row', alignItems: 'center', gap: spacing.sm, flexWrap: 'wrap' }}>
188	                    <View
189	                      style={[
190	                        styles.expiryPill,
191	                        {
192	                          backgroundColor: colors.bg,
193	                          borderColor: colors.border,
194	                        },
195	                      ]}
196	                    >
197	                      <Text variant="labelLarge" color={colors.fg}>
198	                        {formatExpiry(lot.expiry)}
199	                      </Text>
200	                    </View>
201	                    {rel ? (
202	                      <Text variant="labelMedium" color={colors.fg}>
203	                        {rel}
204	                      </Text>
205	                    ) : null}
206	                    {isFefoSuggested && (
207	                      <Text variant="labelMedium" color={palette.primary}>
208	                        ← {t('suggested')}
209	                      </Text>
210	                    )}
211	                  </View>
212	                );
213	              })()}
214	              {/* Per-lot count: "1 / 4" with the taken number colored. No
215	                  unit suffix — the header hint covers it. */}
216	              <View style={{ flexDirection: 'row', alignItems: 'baseline', marginTop: 6, gap: 2 }}>
217	                <Text
218	                  variant="titleLarge"
219	                  color={lot.take > 0 ? (lotComplete ? palette.primary : palette.onSurface) : palette.onSurfaceVariant}
220	                  style={{ fontWeight: '700' }}
221	                >
222	                  {fmtNum(lot.take)}
223	                </Text>
224	                <Text variant="bodyMedium" color={palette.onSurfaceVariant}>
225	                  {' / '}{fmtNum(lot.available)}
226	                </Text>
227	              </View>
228	            </View>
229	            {decimal ? (
230	              <TextInput
231	                value={lot.take === 0 ? '' : String(lot.take)}
232	                onChangeText={(txt) => {
233	                  const cleaned = txt.replace(/[^0-9.]/g, '');
234	                  const n = cleaned === '' || cleaned === '.' ? 0 : Number(cleaned);
235	                  const safe = Number.isFinite(n) ? n : 0;
236	                  const clamped = Math.max(0, Math.min(lot.available, safe));
237	                  onChange(lots.map((l, idx) => (idx === i ? { ...l, take: clamped } : l)));
238	                }}
239	                keyboardType="decimal-pad"
240	                placeholder="0"
241	                placeholderTextColor={palette.onSurfaceVariant}
242	                style={[
243	                  styles.decimalInput,
244	                  {
245	                    borderColor: palette.outline,
246	                    color: palette.onSurface,
247	                    backgroundColor: palette.surface,
248	                  },
249	                ]}
250	              />
251	            ) : (
252	              <CompactStepper
253	                value={lot.take}
