1	import { NativeStackScreenProps } from '@react-navigation/native-stack';
2	import { HandCoins, PackagePlus, Pencil, Search, type LucideIcon } from 'lucide-react-native';
3	import React, { useCallback, useEffect, useMemo, useState } from 'react';
4	import { FlatList, LayoutAnimation, Platform, Pressable, RefreshControl, StyleSheet, TextInput, View, KeyboardAvoidingView } from 'react-native';
5	import {
6	  AppBar,
7	  Card,
8	  radius,
9	  Skeleton,
10	  spacing,
11	  Text,
12	} from '../../../design';
13	import { listStock, statusFor, StockRow, replaceStockFromRemote } from '../../../db/stock';
14	import { pruneLotsToBarcodes, replaceLotsLocal } from '../../../db/lots';
15	import { useT } from '../../../i18n';
16	import { StringKey } from '../../../i18n/strings';
17	import { RootStackParamList } from '../../../navigation/types';
18	import { api } from '../../../sync/api';
19	import { flushOnce } from '../../../sync/syncService';
20	import { FilterDropdown, FilterOption } from '../components/FilterDropdown';
21	import { useTheme } from '../../../theme';
22	import { onCacheStateChange, useCacheStatus } from '../../../sync/cacheStatus';
23	import { invalidateRefetchThrottle, refetchThrottled } from '../../../sync/refetch';
24	import { formatOnHandShort } from '../../../units';
25	
26	type Props = NativeStackScreenProps<RootStackParamList, 'Stock'>;
27	
28	/** Card background per stock health — design uses white for OK, amber tint for LOW, red tint for OUT */
29	function cardBg(row: StockRow): string {
30	  const s = statusFor(row);
31	  if (s === 'out') return '#FFEBEE';
32	  if (s === 'low') return '#FFF8E1';
33	  return '#FFFFFF';
34	}
35	
36	/** Vertical color strip on the left edge of each stock card */
37	function stripColor(row: StockRow): string {
38	  const s = statusFor(row);
39	  if (s === 'out') return '#E53935';
40	  if (s === 'low') return '#F9A825';
41	  return '#43A047';
42	}
43	
44	/** Count text color per stock health */
45	function countColor(row: StockRow): string {
46	  const s = statusFor(row);
47	  if (s === 'out') return '#E53935';
48	  if (s === 'low') return '#F9A825';
49	  if (row.on_hand >= row.threshold * 2) return '#43A047';
50	  return '#66BB6A';
51	}
52	
53	/**
54	 * Split the on-hand display into a big number and a small unit label so the
55	 * count column reads as "86" / "kg" (design) instead of a single ragged
56	 * "86 kg" string. formatOnHandShort never puts a space inside the number
57	 * (thousands use commas), so the last space cleanly separates value/unit.
58	 */
59	function countParts(row: StockRow): { value: string; unit: string } {
60	  const full = formatOnHandShort(row.on_hand, row.pack_size, row.unit);
61	  const i = full.lastIndexOf(' ');
62	  if (i === -1) return { value: full, unit: '' };
63	  return { value: full.slice(0, i), unit: full.slice(i + 1) };
64	}
65	
66	// Stable keys drive the filter logic; labels are resolved per-render via
67	// t() so they follow the active language.
68	const STATUS_OPTIONS: { key: string; labelKey: StringKey }[] = [
69	  { key: 'All', labelKey: 'statusAll' },
70	  { key: 'In Stock', labelKey: 'statusInStock' },
71	  { key: 'Low', labelKey: 'statusLow' },
72	  { key: 'Out', labelKey: 'statusOut' },
73	];
74	
75	export function StockScreen({ route, navigation }: Props) {
76	  const t = useT();
77	  const { palette } = useTheme();
78	  const [rows, setRows] = useState<StockRow[]>([]);
79	  const [query, setQuery] = useState('');
80	  const [category, setCategory] = useState('All');
81	  const [statusFilter, setStatusFilter] = useState('All');
82	  const [refreshing, setRefreshing] = useState(false);
83	  // False until the first local read resolves — stops the "Nothing
84	  // matches" empty state flashing before readLocal() returns (warmCache
85	  // flips hasEverBeenWarm at login, before this screen mounts).
86	  const [loadedLocal, setLoadedLocal] = useState(false);
87	  // Smart Stock Card: which card is expanded to show action buttons.
88	  // Supports deep-linking via route params (e.g. from AlertsScreen).
89	  const [expandedBarcode, setExpandedBarcode] = useState<string | null>(
90	    route.params?.expandBarcode ?? null,
91	  );
92	  const stockStatus = useCacheStatus('stock');
93	  // Skeleton until the first local read lands, OR while we have NEVER
94	  // successfully warmed the stock cache this session AND we're not
95	  // sitting on a known failure state (error / offline) — in those
96	  // terminal states we'd rather show whatever's in local SQLite than a
97	  // forever-spinner.
98	  const showInitialSkeleton =
99	    !loadedLocal ||
100	    (!stockStatus.hasEverBeenWarm &&
101	      stockStatus.state !== 'error' &&
102	      stockStatus.state !== 'offline');
103	
104	  const categoryOptions = useMemo<FilterOption[]>(() => {
105	    const cats = new Set(rows.map((r) => r.category).filter(Boolean) as string[]);
106	    return [{ key: 'All', label: t('allCategories') }, ...Array.from(cats).sort().map((c) => ({ key: c, label: c }))];
107	  }, [rows, t]);
108	  const statusOptions = useMemo<FilterOption[]>(
109	    () => STATUS_OPTIONS.map((o) => ({ key: o.key, label: t(o.labelKey) })),
110	    [t],
111	  );
112	
113	  // Pull the latest stock from the server and replace the local cache.
114	  // Throws on failure so refetchThrottled() can flip the cache state to
115	  // error / offline appropriately. flushOnce() runs first so any
116	  // just-queued local writes hit the server before this read.
117	  const fetchRemote = useCallback(async () => {
118	    await flushOnce().catch(() => {});
119	    const remote = await api.fetch.stock();
120	    await replaceStockFromRemote(
121	      remote.map((r) => ({
122	        barcode: r.barcode,
123	        name: r.name,
124	        category: r.category,
125	        unit: r.unit,
126	        pack_size: r.pack_size != null ? Number(r.pack_size) : null,
127	        dispense_mode: r.dispense_mode ?? 'pack',
128	        on_hand: Number(r.on_hand),
129	        threshold: Number(r.threshold),
130	      })),
131	    );
132	    for (const r of remote) {
133	      await replaceLotsLocal(
134	        r.barcode,
135	        (r.lots ?? []).map((l) => ({
136	          expiry_date: l.expiry_date,
137	          qty: Number(l.qty),
138	        })),
139	      );
140	    }
141	    await pruneLotsToBarcodes(remote.map((r) => r.barcode));
142	  }, []);
143	
144	  const readLocal = useCallback(async () => {
145	    setRows(await listStock());
146	    setLoadedLocal(true);
147	  }, []);
148	
149	  // Always refetch on focus; the throttle in refetchThrottled stops a
150	  // back-tap burst from firing N parallel requests.
151	  const refresh = useCallback(async () => {
152	    await refetchThrottled('stock', fetchRemote);
153	    await readLocal();
154	  }, [fetchRemote, readLocal]);
155	
156	  useEffect(() => {
157	    void readLocal();
158	    void refresh();
159	    const unsub = navigation.addListener('focus', () => { void refresh(); });
160	    // Subscribe to cache state changes too — warmCache or
161	    // post-write invalidation in flushOnce can update the cache from
162	    // outside this screen; re-read SQLite so the list reflects it.
163	    const unsubCache = onCacheStateChange('stock', (s) => {
164	      if (s.state === 'warm') void readLocal();
165	    });
166	    return () => { unsub(); unsubCache(); };
167	  }, [navigation, refresh, readLocal]);
168	
169	  const onRefresh = useCallback(async () => {
170	    // Pull-to-refresh is a user-initiated request — never skip it.
171	    invalidateRefetchThrottle('stock');
172	    setRefreshing(true);
173	    try {
174	      await refresh();
175	    } finally {
176	      setRefreshing(false);
177	    }
178	  }, [refresh]);
179	
180	  const filtered = useMemo(() => {
181	    const q = query.trim().toLowerCase();
182	    return rows.filter((r) => {
183	      if (category !== 'All' && r.category !== category) return false;
184	      if (statusFilter !== 'All') {
185	        const s = statusFor(r);
186	        if (statusFilter === 'In Stock' && s !== 'ok') return false;
187	        if (statusFilter === 'Low' && s !== 'low') return false;
188	        if (statusFilter === 'Out' && s !== 'out') return false;
189	      }
190	      if (!q) return true;
191	      return r.name.toLowerCase().includes(q) || r.barcode.includes(q) || (r.category ?? '').toLowerCase().includes(q);
192	    });
193	  }, [rows, query, category, statusFilter]);
194	
195	  return (
196	    <View style={[styles.safe, { backgroundColor: palette.background }]}>
197	      <AppBar title={t('stock')} subtitle={t('stockSub')} onBack={() => navigation.goBack()} />
198	      <KeyboardAvoidingView
199	        behavior={Platform.OS === 'ios' ? 'padding' : undefined}
200	        style={{ flex: 1 }}
201	      >
202	        <View style={styles.search}>
203	        <View
204	          style={[
205	            styles.searchBox,
206	            {
207	              backgroundColor: palette.surfaceContainerLowest,
208	              borderColor: palette.outlineVariant,
209	            },
210	          ]}
211	        >
212	          <Search size={20} color={palette.onSurfaceVariant} strokeWidth={2} />
213	          <TextInput
214	            value={query}
215	            onChangeText={setQuery}
216	            placeholder={t('search')}
217	            placeholderTextColor={palette.onSurfaceVariant}
218	            style={[styles.searchInput, { color: palette.onSurface }]}
219	          />
220	        </View>
221	      </View>
222	
223	      {/* Dropdown filter row */}
224	      <View style={styles.filterRow}>
225	        <FilterDropdown
226	          label={t('filterCategory')}
227	          options={categoryOptions}
228	          selected={category}
229	          onSelect={setCategory}
230	        />
231	        <FilterDropdown
232	          label={t('filterStatus')}
233	          options={statusOptions}
234	          selected={statusFilter}
235	          onSelect={setStatusFilter}
236	        />
237	      </View>
238	
239	      {showInitialSkeleton && rows.length === 0 ? (
240	        <View style={styles.list}>
241	          {[0, 1, 2].map((i) => (
242	            <View key={i} style={{ marginBottom: spacing.sm }}>
243	              <Card tone="filled" padding="lg">
244	                <View style={styles.row}>
245	                  <View style={{ flex: 1, gap: 6 }}>
246	                    <Skeleton width="60%" height={18} />
247	                    <Skeleton width="40%" height={14} />
248	                  </View>
249	                  <Skeleton width={40} height={24} />
250	                </View>
251	              </Card>
252	            </View>
253	          ))}
254	        </View>
255	      ) : (
256	      <FlatList
257	        data={filtered}
258	        keyExtractor={(r) => r.barcode}
259	        contentContainerStyle={styles.list}
260	        refreshControl={
261	          <RefreshControl refreshing={refreshing} onRefresh={onRefresh} tintColor={palette.primary} />
262	        }
263	        ItemSeparatorComponent={() => <View style={{ height: spacing.sm }} />}
264	        renderItem={({ item }) => {
265	          const isExpanded = expandedBarcode === item.barcode;
266	          const status = statusFor(item);
267	          const count = countParts(item);
268	          return (
269	          <Card
270	            tone="elevated"
271	            padding="lg"
272	            style={{ backgroundColor: cardBg(item) }}
273	            onPress={() => {
274	              LayoutAnimation.configureNext(LayoutAnimation.Presets.easeInEaseOut);
275	              setExpandedBarcode((prev) => (prev === item.barcode ? null : item.barcode));
276	            }}
277	          >
278	            <View style={styles.row}>
279	              {/* Color strip — visual status indicator */}
280	              <View style={[styles.strip, { backgroundColor: stripColor(item) }]} />
281	              <View style={styles.nameCol}>
282	                <Text variant="titleMedium" style={{ fontWeight: '700' }} numberOfLines={1}>
283	                  {item.name}
284	                </Text>
285	                <Text
286	                  variant="bodyMedium"
287	                  color={palette.onSurfaceVariant}
288	                  style={{ marginTop: 2 }}
289	                  numberOfLines={1}
290	                >
291	                  {item.category ?? '—'}
292	                </Text>
293	              </View>
294	              <View style={styles.countCol}>
295	                <Text
296	                  color={countColor(item)}
297	                  style={styles.countValue}
298	                  numberOfLines={1}
299	                >
300	                  {count.value}
301	                </Text>
302	                {status === 'out' ? (
303	                  <Text color="#E53935" style={styles.countLabel}>OUT</Text>
304	                ) : status === 'low' ? (
