1	import { useFocusEffect, useIsFocused } from '@react-navigation/native';
2	import { NativeStackScreenProps } from '@react-navigation/native-stack';
3	import { Keyboard, List, X, Zap, ZapOff } from 'lucide-react-native';
4	import React, { useCallback, useEffect, useRef, useState } from 'react';
5	import {
6	  Animated,
7	  Dimensions,
8	  Easing,
9	  KeyboardAvoidingView,
10	  Platform,
11	  Pressable,
12	  StyleSheet,
13	  TextInput,
14	  View,
15	} from 'react-native';
16	import { SafeAreaView } from 'react-native-safe-area-context';
17	import {
18	  Camera,
19	  Code,
20	  useCameraDevice,
21	  useCameraPermission,
22	  useCodeScanner,
23	} from 'react-native-vision-camera';
24	import { Button, IconButton, radius, spacing, Text } from '../../../design';
25	import { findProduct, upsertProduct } from '../../../db/products';
26	import { findCanonicalProductByBarcode } from '../../../db/catalog';
27	import { useT } from '../../../i18n';
28	import { RootStackParamList } from '../../../navigation/types';
29	import { api } from '../../../sync/api';
30	import { haptic } from '../../../utils/haptics';
31	import { useTheme } from '../../../theme';
32	
33	type Props = NativeStackScreenProps<RootStackParamList, 'Scanner'>;
34	
35	// Vision-camera / ML Kit format names. Order doesn't affect decoding —
36	// every frame is tried against every requested format. Listed broadly so
37	// dense GS1-128 SSCC labels, EAN/UPC products, QR, DataMatrix all work.
38	// Product barcodes are always 1D symbologies. We deliberately do NOT
39	// scan QR / data-matrix / PDF-417 / Aztec — they're 2D codes used for
40	// things like Expo's dev-client launch QR or general-purpose URLs, and
41	// the camera would happily route those into the Receiving form as if
42	// they were barcodes (seen with `exp+field-app://expo-development-client/…`
43	// in field testing).
44	const CODE_TYPES = [
45	  'code-128',
46	  'code-39',
47	  'code-93',
48	  'codabar',
49	  'ean-13',
50	  'ean-8',
51	  'itf',
52	  'upc-a',
53	  'upc-e',
54	] as const;
55	
56	// ML Kit v4+ has strong internal confidence scoring. We no longer require
57	// a 2-read confirmation gate — that was the main cause of "I have to wave
58	// the barcode back and forth" sluggishness. A single valid decode is
59	// accepted immediately.
60	
61	export function ScannerScreen({ navigation }: Props) {
62	  const { palette } = useTheme();
63	  const t = useT();
64	  const { hasPermission, requestPermission } = useCameraPermission();
65	  const device = useCameraDevice('back');
66	  // Only keep the camera session alive while this screen has focus.
67	  // Native-stack keeps prior screens mounted on push, so without this
68	  // gate the camera stays active behind Receiving / RegisterProduct
69	  // and re-entering Scanner throws session/invalid-output-configuration
70	  // because the session is already running.
71	  const isFocused = useIsFocused();
72	  const [torch, setTorch] = useState(false);
73	  const [manualOpen, setManualOpen] = useState(false);
74	  const [manualValue, setManualValue] = useState('');
75	
76	  // acceptedRef — true while a code is being routed; blocks further reads.
77	  const acceptedRef = useRef(false);
78	
79	  // Reset on every screen focus so returning from the order session flow
80	  // allows scanning the next item without remounting the screen.
81	  useFocusEffect(
82	    useCallback(() => {
83	      acceptedRef.current = false;
84	    }, []),
85	  );
86	
87	  const flashOpacity = useRef(new Animated.Value(0)).current;
88	  const pulse = useRef(new Animated.Value(0)).current;
89	
90	  useEffect(() => {
91	    if (!hasPermission) requestPermission();
92	  }, [hasPermission, requestPermission]);
93	
94	  // Pulse the reticle border to communicate omnidirectional detection.
95	  useEffect(() => {
96	    const anim = Animated.loop(
97	      Animated.sequence([
98	        Animated.timing(pulse, {
99	          toValue: 1,
100	          duration: 900,
101	          easing: Easing.inOut(Easing.ease),
102	          useNativeDriver: true,
103	        }),
104	        Animated.timing(pulse, {
105	          toValue: 0,
106	          duration: 900,
107	          easing: Easing.inOut(Easing.ease),
108	          useNativeDriver: true,
109	        }),
110	      ]),
111	    );
112	    anim.start();
113	    return () => anim.stop();
114	  }, [pulse]);
115	
116	  const flash = useCallback(() => {
117	    flashOpacity.setValue(0.6);
118	    Animated.timing(flashOpacity, {
119	      toValue: 0,
120	      duration: 240,
121	      useNativeDriver: true,
122	    }).start();
123	  }, [flashOpacity]);
124	
125	  /**
126	   * Route a barcode to the next screen. Local catalog → Receiving;
127	   * otherwise ask the backend; final fallback is the registration flow.
128	   */
129	  const routeFor = useCallback(
130	    async (raw: string) => {
131	      // First check: canonical product catalog (barcode → product_id)
132	      const canonical = await findCanonicalProductByBarcode(raw).catch(() => null);
133	      if (canonical) {
134	        navigation.push('Receiving', {
135	          barcode: raw,
136	          productId: canonical.product_id,
137	          productName: canonical.canonical_name,
138	          unit: canonical.unit,
139	          packSize: canonical.pack_size,
140	        });
141	        return;
142	      }
143	
144	      // Second check: legacy local products table
145	      const local = await findProduct(raw).catch(() => null);
146	      if (local) {
147	        navigation.push('Receiving', {
148	          barcode: raw,
149	          packSize: local.pack_size ?? undefined,
150	        });
151	        return;
152	      }
153	
154	      // Third check: backend catalog
155	      try {
156	        const hit = await api.fetch.catalog(raw);
157	        if (hit.product) {
158	          await upsertProduct({
159	            barcode: hit.product.barcode,
160	            name: hit.product.name,
161	            category: hit.product.category,
162	            unit: hit.product.unit,
163	            pack_size: hit.product.pack_size ?? null,
164	          });
165	          navigation.push('Receiving', {
166	            barcode: raw,
167	            packSize: hit.product.pack_size ?? undefined,
168	          });
169	          return;
170	        }
171	      } catch {
172	        // Offline / 401 — fall through.
173	      }
174	
175	      // Barcode not in any catalog — go straight to the registration form
176	      // so the user can name + categorise the product. The catalog list is
177	      // surfaced inline as fuzzy suggestions on the name input itself.
178	      navigation.push('RegisterProduct', { barcode: raw });
179	    },
180	    [navigation],
181	  );
182	
183	  /** A scanned code is only a usable product barcode if it looks like
184	   *  one — UPC/EAN/ITF/Code128 are alphanumeric (mostly digits) with
185	   *  no whitespace. We already restrict the scanner to 1D code types,
186	   *  but defense in depth: also reject any URI-scheme string
187	   *  (http://, exp+field-app://, mailto:, tel:, etc.) in case a 1D
188	   *  barcode ever carried URL-like text. */
189	  const looksLikeBarcode = (raw: string): boolean => {
190	    const v = raw.trim();
191	    if (v.length < 4 || v.length > 32) return false;
192	    // Any URI scheme — "scheme:" or "scheme://" — is not a product barcode.
193	    if (/^[a-z][a-z0-9+.-]*:/i.test(v)) return false;
194	    if (/\s/.test(v)) return false;
195	    // Allow alphanumerics, dashes, underscores (covers EAN/UPC + serials).
196	    return /^[A-Za-z0-9_-]+$/.test(v);
197	  };
198	
199	  /** Entry point for both camera scans (after the 2-read gate) and manual entry. */
200	  const acceptCode = useCallback(
201	    (raw: string) => {
202	      if (acceptedRef.current) return;
203	      if (!looksLikeBarcode(raw)) {
204	        // Soft-reject: brief haptic so the user knows the read fired,
205	        // but don't navigate. The camera will detect again on the next
206	        // frame, hopefully landing on the actual product barcode.
207	        haptic.warn();
208	        return;
209	      }
210	      acceptedRef.current = true;
211	      haptic.success();
212	      flash();
213	      routeFor(raw.trim());
214	    },
215	    [flash, routeFor],
216	  );
217	
218	  const onCodeScanned = useCallback(
219	    (codes: Code[]) => {
220	      if (acceptedRef.current) return;
221	      // Accept the first code with a non-empty value immediately.
222	      // ML Kit v4+ has its own internal confidence scoring so a single
223	      // detection is reliable. The old 2-read gate added 150-300ms
224	      // latency and required the user to hold very still.
225	      const first = codes.find((c) => c.value);
226	      if (!first?.value) return;
227	      acceptCode(first.value);
228	    },
229	    [acceptCode],
230	  );
231	
232	  const codeScanner = useCodeScanner({
233	    codeTypes: [...CODE_TYPES],
234	    onCodeScanned,
235	  });
236	
237	  const submitManual = useCallback(() => {
238	    const v = manualValue.trim();
239	    if (!v) return;
240	    // Apply the same shape check as camera scans — paste-from-clipboard
241	    // or autofill can drop a URL into the manual field too.
242	    if (!looksLikeBarcode(v)) {
243	      haptic.warn();
244	      return;
245	    }
246	    setManualOpen(false);
247	    setManualValue('');
248	    if (acceptedRef.current) return;
249	    acceptedRef.current = true;
250	    haptic.success();
251	    routeFor(v);
252	  }, [manualValue, routeFor]);
253	
254	  const pulseScale = pulse.interpolate({ inputRange: [0, 1], outputRange: [1, 1.04] });
255	  const pulseOpacity = pulse.interpolate({ inputRange: [0, 1], outputRange: [0.55, 1] });
256	
257	  if (!hasPermission) {
258	    return (
259	      <SafeAreaView style={[styles.permission, { backgroundColor: palette.background }]}>
260	        <Text variant="headlineSmall" style={{ textAlign: 'center', marginBottom: spacing.md }}>
261	          {t('cameraNeeded')}
262	        </Text>
263	        <Text
264	          variant="bodyLarge"
265	          color={palette.onSurfaceVariant}
266	          style={{ textAlign: 'center', marginBottom: spacing.xl }}
267	        >
268	          {t('cameraHint')}
269	        </Text>
270	        <Button label={t('allowCamera')} onPress={requestPermission} size="lg" fullWidth />
271	        <Button
272	          label={t('notNow')}
273	          variant="text"
274	          onPress={() => navigation.goBack()}
275	          style={{ marginTop: spacing.sm }}
276	        />
277	      </SafeAreaView>
278	    );
279	  }
280	
281	  if (!device) {
282	    return (
283	      <SafeAreaView style={[styles.permission, { backgroundColor: palette.background }]}>
284	        <Text variant="headlineSmall" style={{ textAlign: 'center' }}>
285	          {t('noCamera')}
286	        </Text>
287	        <Button
288	          label={t('back')}
289	          variant="text"
290	          onPress={() => navigation.goBack()}
291	          style={{ marginTop: spacing.md }}
292	        />
293	      </SafeAreaView>
294	    );
295	  }
296	
297	  return (
298	    <View style={styles.root}>
299	      <Camera
300	        style={StyleSheet.absoluteFill}
301	        device={device}
302	        isActive={isFocused}
303	        torch={torch ? 'on' : 'off'}
304	        codeScanner={codeScanner}
305	        resizeMode="cover"
306	      />
307	
308	      {/* Dimmed border around the reticle. Pure cosmetics — detection
309	          is full-frame, so this is just a "look here" hint. */}
310	      <View pointerEvents="none" style={styles.maskTop} />
311	      <View pointerEvents="none" style={styles.maskRow}>
312	        <View style={styles.maskSide} />
313	        <View style={styles.window}>
314	          <Animated.View
315	            pointerEvents="none"
316	            style={[
317	              styles.reticle,
318	              {
319	                opacity: pulseOpacity,
320	                transform: [{ scale: pulseScale }],
321	                borderColor: palette.primaryContainer,
322	              },
323	            ]}
324	          />
325	        </View>
326	        <View style={styles.maskSide} />
327	      </View>
328	      <View pointerEvents="none" style={styles.maskBottom} />
329	
330	      <Animated.View pointerEvents="none" style={[styles.flash, { opacity: flashOpacity }]} />
331	
332	      <SafeAreaView edges={['top']} style={styles.topBar}>
333	        <View style={styles.topBarRow}>
334	          <IconButton Icon={X} onPress={() => navigation.goBack()} tone="inverse" />
335	          <Text variant="titleMedium" color="#fff">
336	            {t('scanBarcode')}
337	          </Text>
338	          <IconButton
339	            Icon={torch ? Zap : ZapOff}
340	            onPress={() => setTorch((t) => !t)}
341	            tone="inverse"
342	          />
343	        </View>
344	      </SafeAreaView>
345	
346	      <SafeAreaView edges={['bottom']} style={styles.bottom}>
347	        <Text
348	          variant="bodyLarge"
349	          color="#fff"
350	          style={{ textAlign: 'center', paddingHorizontal: spacing.xl }}
351	        >
352	          {t('holdSteadyHint')}
353	        </Text>
354	        <Pressable
355	          onPress={() => setManualOpen(true)}
356	          hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
357	          style={({ pressed }) => [
358	            styles.typeBtn,
359	            { backgroundColor: pressed ? '#ffffff22' : '#ffffff11' },
360	          ]}
361	        >
362	          <Keyboard size={18} color="#fff" strokeWidth={2.2} />
363	          <Text variant="labelLarge" color="#fff">
364	            {t('enterCode')}
365	          </Text>
366	        </Pressable>
367	        <Pressable
368	          onPress={() => {
369	            if (acceptedRef.current) return;
370	            acceptedRef.current = true;
371	            haptic.tap();
372	            navigation.push('CatalogPicker', { barcode: undefined });
373	          }}
374	          hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
375	          style={({ pressed }) => [
376	            styles.typeBtn,
377	            { backgroundColor: pressed ? '#ffffff22' : '#ffffff11', marginTop: spacing.sm },
378	          ]}
379	        >
380	          <List size={18} color="#fff" strokeWidth={2.2} />
381	          <Text variant="labelLarge" color="#fff">
382	            {t('noBarcode')}
383	          </Text>
384	        </Pressable>
385	      </SafeAreaView>
386	
387	      {manualOpen && (
388	        <Pressable style={styles.modalBackdrop} onPress={() => setManualOpen(false)}>
389	          <KeyboardAvoidingView
390	            behavior={Platform.OS === 'ios' ? 'padding' : undefined}
391	            style={styles.modalCenter}
392	            pointerEvents="box-none"
393	          >
394	            <Pressable
395	              onPress={(e) => e.stopPropagation()}
396	              style={[styles.modalCard, { backgroundColor: palette.surface }]}
397	            >
398	              <Text variant="titleLarge">{t('typeBarcode')}</Text>
399	              <Text
400	                variant="bodyMedium"
401	                color={palette.onSurfaceVariant}
402	                style={{ marginTop: spacing.xs }}
403	              >
404	                {t('damagedLabelHint')}
405	              </Text>
406	              <TextInput
407	                value={manualValue}
408	                onChangeText={setManualValue}
409	                placeholder={t('barcodeExample')}
410	                placeholderTextColor={palette.onSurfaceVariant}
411	                keyboardType="number-pad"
412	                autoFocus
413	                returnKeyType="done"
414	                onSubmitEditing={submitManual}
415	                style={[
416	                  styles.modalInput,
417	                  {
418	                    backgroundColor: palette.surfaceContainerLowest,
419	                    borderColor: palette.outlineVariant,
420	                    color: palette.onSurface,
421	                  },
422	                ]}
423	              />
424	              <View style={styles.modalActions}>
425	                <Button
426	                  label={t('cancel')}
427	                  variant="text"
428	                  size="md"
429	                  onPress={() => setManualOpen(false)}
430	                />
431	                <Button
432	                  label={t('useCode')}
433	                  size="md"
434	                  disabled={manualValue.trim().length === 0}
435	                  onPress={submitManual}
436	                />
437	              </View>
438	            </Pressable>
439	          </KeyboardAvoidingView>
440	        </Pressable>
441	      )}
442	    </View>
443	  );
444	}
445	
446	// Reticle covers most of the screen width so the user has plenty of room
447	// to frame a barcode at any rotation. Detection is full-frame regardless —
448	// the reticle is purely a "look here" hint.
449	const WINDOW = Math.min(Dimensions.get('window').width - 24, 400);
450	
451	const styles = StyleSheet.create({
452	  root: { flex: 1, backgroundColor: '#000' },
453	  permission: {
454	    flex: 1,
455	    padding: spacing.xl,
456	    justifyContent: 'center',
457	  },
458	  topBar: { position: 'absolute', top: 0, left: 0, right: 0 },
459	  topBarRow: {
460	    flexDirection: 'row',
461	    alignItems: 'center',
462	    justifyContent: 'space-between',
463	    paddingHorizontal: spacing.md,
464	    paddingVertical: spacing.sm,
465	  },
466	  maskTop: { flex: 1, backgroundColor: 'rgba(0,0,0,0.45)' },
467	  maskBottom: { flex: 1.4, backgroundColor: 'rgba(0,0,0,0.45)' },
468	  maskRow: { flexDirection: 'row', height: WINDOW },
469	  maskSide: { flex: 1, backgroundColor: 'rgba(0,0,0,0.45)' },
470	  window: { width: WINDOW, height: WINDOW, overflow: 'visible' },
471	  reticle: {
472	    ...StyleSheet.absoluteFillObject,
473	    borderWidth: 3,
474	    borderRadius: 18,
475	  },
476	  flash: { ...StyleSheet.absoluteFillObject, backgroundColor: '#fff' },
477	  bottom: {
478	    position: 'absolute',
479	    bottom: 0,
480	    left: 0,
481	    right: 0,
482	    paddingBottom: spacing.lg,
483	    alignItems: 'center',
484	    gap: spacing.md,
485	  },
486	  typeBtn: {
487	    marginTop: spacing.md,
488	    flexDirection: 'row',
489	    alignItems: 'center',
490	    gap: spacing.sm,
491	    paddingHorizontal: spacing.xl,
492	    paddingVertical: spacing.sm,
493	    borderRadius: radius.pill,
494	    borderWidth: 1,
495	    borderColor: '#ffffff66',
496	    overflow: 'hidden',
497	  },
498	  modalBackdrop: {
499	    ...StyleSheet.absoluteFillObject,
500	    backgroundColor: 'rgba(0,0,0,0.55)',
501	  },
502	  modalCenter: {
503	    flex: 1,
504	    alignItems: 'center',
505	    justifyContent: 'center',
506	    paddingHorizontal: spacing.xl,
507	  },
508	  modalCard: {
509	    width: '100%',
510	    maxWidth: 420,
511	    borderRadius: radius.lg,
512	    padding: spacing.xl,
513	  },
514	  modalInput: {
515	    marginTop: spacing.lg,
516	    borderRadius: radius.md,
517	    borderWidth: 1.5,
518	    paddingHorizontal: spacing.lg,
519	    minHeight: 56,
520	    fontSize: 18,
521	    letterSpacing: 1,
522	  },
523	  modalActions: {
524	    flexDirection: 'row',
525	    justifyContent: 'flex-end',
526	    gap: spacing.sm,
527	    marginTop: spacing.lg,
528	  },
529	});
