1	import { getDb, now } from './database';
2	
3	export type KnownProduct = {
4	  barcode: string;
5	  name: string;
6	  category: string | null;
7	  unit: string | null;
8	  pack_size: number | null;
9	};
10	
11	/**
12	 * Union of every product the device knows about: locally-registered
13	 * products + every row mirrored from the remote stock cache. Used by
14	 * the fuzzy-suggest hook so the user can be offered an existing name
15	 * before they type it out from scratch (or misspell it).
16	 *
17	 * Dedups on barcode, preferring the locally-registered product entry
18	 * when both sources have it (it's the authoritative name on this device).
19	 */
20	export async function listKnownProducts(): Promise<KnownProduct[]> {
21	  const db = await getDb();
22	  const rows = await db.getAllAsync<KnownProduct>(`
23	    SELECT barcode, name, category, unit, pack_size FROM products
24	    UNION
25	    SELECT barcode, name, category, unit, NULL AS pack_size FROM stock_levels
26	    WHERE barcode NOT IN (SELECT barcode FROM products)
27	    ORDER BY name COLLATE NOCASE
28	  `);
29	  return rows;
30	}
31	
32	// ─── Canonical Product Catalog ───────────────────────────────────
33	
34	export type CanonicalProduct = {
35	  product_id: string;
36	  canonical_name: string;
37	  category: string | null;
38	  hsn_code: string | null;
39	  unit: string;
40	  pack_size: number;
41	  /** Defaulted to 'pack' at the DB layer when omitted by writers. */
42	  dispense_mode?: 'pack' | 'divisible';
43	  /** 1 if any barcode is mapped to this product on the server, else 0.
44	   *  Drives the "hide already-taken products" filter when registering a
45	   *  brand-new barcode. SQLite has no bool, so it's stored as 0/1. */
46	  has_barcode: number;
47	  /** Most-recently learned real barcode mapped to this product on the
48	   *  server, or null. Read by the "No barcode" pick flow so it reuses
49	   *  the existing mapping instead of falling back to a synthetic id. */
50	  primary_barcode: string | null;
51	  updated_at: number;
52	};
53	
54	export async function listCanonicalProducts(): Promise<CanonicalProduct[]> {
55	  const db = await getDb();
56	  return db.getAllAsync<CanonicalProduct>(
57	    'SELECT * FROM canonical_products ORDER BY canonical_name',
58	  );
59	}
60	
61	export async function findCanonicalProductById(
62	  productId: string,
63	): Promise<CanonicalProduct | null> {
64	  const db = await getDb();
65	  return db.getFirstAsync<CanonicalProduct>(
66	    'SELECT * FROM canonical_products WHERE product_id = ?',
67	    [productId],
68	  );
69	}
70	
71	export async function findCanonicalProductByBarcode(
72	  barcode: string,
73	): Promise<CanonicalProduct | null> {
74	  const db = await getDb();
75	  return db.getFirstAsync<CanonicalProduct>(
76	    `SELECT cp.* FROM canonical_products cp
77	     JOIN product_barcodes pb ON pb.product_id = cp.product_id
78	     WHERE pb.barcode = ?`,
79	    [barcode],
80	  );
