export async function listLowOrOut(siteId: string): Promise<InventoryStockListRow[]> {
  const db = await getDb();
  const result = await db.execute({
    sql: `
      SELECT ${STOCK_SELECT},
        to_char(s.nearest_expiry, 'YYYY-MM-DD') AS nearest_expiry,
        COALESCE(
          (SELECT json_agg(json_build_object(
                    'expiry_date', to_char(l.expiry_date, 'YYYY-MM-DD'),
                    'qty', l.qty)
                  ORDER BY l.expiry_date NULLS LAST)
             FROM inventory_stock_lots l
            WHERE l.site_id = s.site_id AND l.barcode = s.barcode AND l.qty > 0),
          '[]'::json
        ) AS lots
      ${STOCK_JOINS}
      WHERE s.site_id = ? AND s.on_hand <= s.threshold
      ORDER BY s.on_hand ASC, s.name ASC
    `,
    args: [siteId],
  });
  return result.rows.map((r) => {
    const row = r as Record<string, unknown>;
    let lots = row.lots as LotSummary[] | string | null;
    if (typeof lots === "string") {
      try { lots = JSON.parse(lots) as LotSummary[]; } catch { lots = []; }
    }
    if (!Array.isArray(lots)) lots = [];
    return {
      ...(row as InventoryStockRow),
      nearest_expiry: (row.nearest_expiry as string | null) ?? null,
      lots: lots.map((l) => ({
        expiry_date: l.expiry_date ?? null,
        qty: Number(l.qty),
      })),
    } as InventoryStockListRow;
  });
}

export async function findStock(
  siteId: string,
  barcode: string,
): Promise<InventoryStockRow | null> {
  const db = await getDb();
  const result = await db.execute({
    sql: `SELECT * FROM inventory_stock WHERE site_id = ? AND barcode = ? LIMIT 1`,
    args: [siteId, barcode],
  });
  return (result.rows[0] as InventoryStockRow | undefined) ?? null;
}

export type InventoryStockJitRow = InventoryStockRow & {
  /** Cached MIN of lot.expiry_date for this barcode (NULL lots ignored).
   *  Source of truth lives in inventory_stock_lots; this column is
   *  recomputed by refreshStockCache() on every lot mutation. */
  nearest_expiry: string | null;
  /** Per-batch breakdown, FEFO-ordered. Lets the field-app's dispense
   *  picker and EditStock screen show "3@A, 4@B, 3@C" instead of just
   *  the nearest date. Caller fills this via listLots after the join. */
  lots: LotSummary[];
};

/**
 * Single-row stock + pack_size + nearest-future-expiry. Used by the
 * field-app's JIT verification on EditStock / Dispense screens. The
 * stock row itself is authoritative; the expiry is a hint.
 */
export async function findStockJit(
  siteId: string,
  barcode: string,
): Promise<InventoryStockJitRow | null> {
  const db = await getDb();
  const result = await db.execute({
    sql: `
      SELECT ${STOCK_SELECT},
        COALESCE(
          to_char(s.nearest_expiry, 'YYYY-MM-DD'),
          (
            SELECT to_char(MIN(r.expiry_date), 'YYYY-MM-DD')
            FROM inventory_receipts r
            WHERE r.site_id = s.site_id
              AND r.barcode = s.barcode
              AND r.expiry_date IS NOT NULL
              AND r.expiry_date >= CURRENT_DATE
          )
        ) AS nearest_expiry
      ${STOCK_JOINS}
      WHERE s.site_id = ? AND s.barcode = ?

