/**
 * Apply a correction directly to inventory_stock. Sets on_hand to the
 * absolute new value (not a delta) so the result on the server matches
 * what the guard saw and confirmed in the field-app.
 */
export async function setStockOnHand(input: {
  siteId: string;
  barcode: string;
  onHand: number;
  /** When provided (including explicit null), overwrites
   *  inventory_stock.nearest_expiry. Null clears the column ("no expiry"
   *  per the guard). Undefined leaves the column untouched. */
  nearestExpiry?: string | null;
  fallbackName?: string;
  fallbackCategory?: string | null;
  fallbackUnit?: string | null;
}): Promise<void> {
  const db = await getDb();
  const touchExpiry = input.nearestExpiry !== undefined;
  const expiryArg: string | null = touchExpiry ? (input.nearestExpiry ?? null) : null;
  await db.execute({
    sql: `
      INSERT INTO inventory_stock (barcode, site_id, name, category, unit, on_hand, threshold, nearest_expiry)
      VALUES (?, ?, ?, ?, ?, GREATEST(?, 0), 0, ?)
      ON CONFLICT (site_id, barcode) DO UPDATE SET
        on_hand = GREATEST(?, 0),
        nearest_expiry = ${touchExpiry ? '?' : 'inventory_stock.nearest_expiry'},
        updated_at = now()
    `,
    args: touchExpiry
      ? [
          input.barcode,
          input.siteId,
          input.fallbackName ?? "Unknown",
          input.fallbackCategory ?? null,
          input.fallbackUnit ?? null,
          input.onHand,
          expiryArg,
          input.onHand,
          expiryArg,
        ]
      : [
          input.barcode,
          input.siteId,
          input.fallbackName ?? "Unknown",
          input.fallbackCategory ?? null,
          input.fallbackUnit ?? null,
          input.onHand,
          null,
          input.onHand,
        ],
  });
}

/**
 * Ensure an inventory_stock row exists for this (site, barcode) so lot
 * writes have a parent row whose on_hand / nearest_expiry can be
 * refreshed by refreshStockCache. Idempotent — no-op if the row already
 * exists, even when the fallback fields differ.

