774:export async function insertStockCorrection(input: {
  newQty: number;
  oldExpiry?: string | null;
  newExpiry?: string | null;
  /** Per-pack expiry dates when the guard turned on "different per pack". */
  newExpiries?: string[] | null;
  deviceId?: string | null;
  guardId?: string | null;
  guardName?: string | null;
  correctedAt: string;
}): Promise<{ inserted: boolean }> {
  const db = await getDb();
  // Postgres DATE[] literal: '{2026-01-01,2026-02-15}'. The libsql/pg shim
  // doesn't auto-box arrays so we hand-encode. Empty array → NULL.
  const expiriesLiteral =
    input.newExpiries && input.newExpiries.length > 0
      ? `{${input.newExpiries.map((d) => `"${d.replace(/"/g, '')}"`).join(",")}}`
      : null;
  const result = await db.execute({
    sql: `
      INSERT INTO inventory_stock_corrections (
        id, site_id, barcode, product_name, old_qty, new_qty,
        old_expiry, new_expiry, new_expiries,
        device_id, guard_id, guard_name, corrected_at
      )
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?::DATE[], ?, ?, ?, ?)
      ON CONFLICT (id) DO NOTHING
    `,
    args: [
      input.id,
      input.siteId,
      input.barcode,
      input.productName,
      input.oldQty,
      input.newQty,
      input.oldExpiry ?? null,
      input.newExpiry ?? null,
      expiriesLiteral,
      input.deviceId ?? null,
      input.guardId ?? null,
      input.guardName ?? null,
      input.correctedAt,
    ],
  });
  return { inserted: (result.rowsAffected ?? 0) > 0 };
}

