/** What produced a shortfall. Dotted event names below are pre-chosen so
 *  a future flow-pack trigger is a one-line drop-in; nothing is
 *  registered with the automation engine yet (see engine CLAUDE.md). */
export type DiscrepancySource = "issue" | "receipt" | "correction";

/** Internal event name for the eventual automation surface. */
export const INVENTORY_STOCK_DISCREPANCY_EVENT = "inventory.stock_discrepancy";

export type StockDiscrepancyRow = {
  id: string;
  site_id: string;
  barcode: string;
  product_name: string;
  source_kind: DiscrepancySource;
  source_event_id: string;
  expected_delta: number;
  applied_delta: number;
  shortfall: number;
  status: "open" | "resolved";
  note: string | null;
  observed_at: string | null;
  detected_at: string;
  resolved_at: string | null;
  resolved_by: string | null;
};

/**
 * Record that a movement could not be applied in full.
 *
 * This is the single typed emit point for `inventory.stock_discrepancy`.
 * Call it wherever a fact gets clamped; do not inline the insert
 * elsewhere, so wiring a flow-pack trigger later stays mechanical.
 *
 * Idempotent on (site, source_kind, source_event_id): an outbox retry of
 * the same client-generated event id will not spawn a second recount
 * request.
 */
export async function recordStockDiscrepancy(input: {
  siteId: string;
  barcode: string;
  productName: string;
  sourceKind: DiscrepancySource;
  sourceEventId: string;
  /** Signed delta the event asked for (negative for a dispense). */
  expectedDelta: number;
  /** Signed delta actually applied. */
  appliedDelta: number;
  observedAt?: string | null;
  note?: string | null;
}): Promise<{ inserted: boolean; shortfall: number }> {
  const shortfall = input.expectedDelta - input.appliedDelta;
  if (Math.abs(shortfall) < 1e-6) return { inserted: false, shortfall: 0 };
  const db = await getDb();
  const result = await db.execute({
    sql: `
      INSERT INTO inventory_stock_discrepancies (
        id, site_id, barcode, product_name, source_kind, source_event_id,
        expected_delta, applied_delta, shortfall, status, note, observed_at
      )
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'open', ?, ?)
      ON CONFLICT (site_id, source_kind, source_event_id) DO NOTHING
    `,
    args: [
      `dsc_${input.sourceKind}_${input.sourceEventId}`,
      input.siteId,
      input.barcode,
      input.productName,
      input.sourceKind,
      input.sourceEventId,
      input.expectedDelta,
      input.appliedDelta,
      shortfall,
      input.note ?? null,
      input.observedAt ?? null,
    ],
  });
  return { inserted: (result.rowsAffected ?? 0) > 0, shortfall };
}

const STOCK_DISCREPANCY_SELECT = `
