  expected_delta, applied_delta, shortfall, status, note,
  observed_at, detected_at, resolved_at, resolved_by
`;

export async function listStockDiscrepancies(
  siteId: string,
  opts?: { status?: "open" | "resolved" | "all" },
): Promise<StockDiscrepancyRow[]> {
  const db = await getDb();
  const status = opts?.status ?? "open";
  const result =
    status === "all"
      ? await db.execute({
          sql: `SELECT ${STOCK_DISCREPANCY_SELECT} FROM inventory_stock_discrepancies
                WHERE site_id = ? ORDER BY detected_at DESC`,
          args: [siteId],
        })
      : await db.execute({
          sql: `SELECT ${STOCK_DISCREPANCY_SELECT} FROM inventory_stock_discrepancies
                WHERE site_id = ? AND status = ? ORDER BY detected_at DESC`,
          args: [siteId, status],
        });
  return result.rows as StockDiscrepancyRow[];
}

