/**
 * Terminal status for one queued write, returned so the field-app can
 * replace "sent" with what actually became of it.
 *
 *  - `applied`                 — landed exactly as recorded.
 *  - `applied_with_adjustment` — landed, but the shelf had less than we
 *                                thought; a recount has been requested.
 *  - `superseded_by_count`     — reserved for v2 (a delta observed before
 *                                an admin count but arriving after it).
 *                                Not emitted under the v1 arrival-order
 *                                policy; the field-app already handles it
 *                                so enabling v2 needs no client release.
 *
 * `note` is one plain sentence for a non-power user. It states what
 * happened and, when relevant, what we did about it. It never asks a
 * question — the only question this system asks a floor user is "can you
 * count what's on the shelf?", and that arrives as a recount task.
 */
export type WriteStatus =
  | "applied"
  | "applied_with_adjustment"
  | "superseded_by_count";

function writeOutcome(input: {
  requested: number;
  applied: number;
  shortfall: number;
  adjustedNote: string;
}): { status: WriteStatus; appliedQty: number; note: string | null } {
  if (input.shortfall > 0) {
    return {
      status: "applied_with_adjustment",
      appliedQty: input.applied,
      note: input.adjustedNote,
    };
  }
  return { status: "applied", appliedQty: input.applied, note: null };
}

