92	  // JIT verification — fetch the server's authoritative on_hand +
93	  // nearest_expiry the moment the screen opens, in parallel with the
94	  // local read. If the server differs, we surface a "Stock has changed"
95	  // prompt before letting the user save. If the fetch fails (timeout /
96	  // offline / 5xx), we block the save entirely — corrections must be
97	  // committed against verified state per the cache-freshness plan.
98	  const [verifyStatus, setVerifyStatus] = useState<VerifyStatus>('verifying');
99	  const [serverQty, setServerQty] = useState<number | null>(null);
100	  const [serverExpiry, setServerExpiry] = useState<string | null>(null);
101	  /** The server's per-batch breakdown, kept so "Use new count" can
102	   *  restore the real lots instead of flattening them into one row. */
103	  const [serverLots, setServerLots] = useState<Batch[] | null>(null);
104	
105	  /**
106	   * Where the batch rows on screen came from. The local read and the JIT
107	   * fetch race each other, so both consult this instead of assuming an
108	   * order. 'remote' wins and is never downgraded — the server's lot
109	   * breakdown is the real one.
110	   */
111	  const seedSource = useRef<'none' | 'local' | 'remote'>('none');
112	  /** Set once the guard edits anything, so a late-arriving JIT response
113	   *  can't wipe what they just typed. */
114	  const userTouched = useRef(false);
115	
116	  const applySeed = (
117	    seed: Batch[],
118	    source: 'local' | 'remote',
119	    qtyRef: number,
120	    expiryRef: string | null,
121	  ) => {
122	    seedSource.current = source;
123	    setOriginalBatches(seed);
124	    setBatches(seed);
125	    setOriginalQty(qtyRef);
126	    setOriginalExpiry(expiryRef);
127	  };
128	
129	  useEffect(() => {
130	    let cancelled = false;
131	    (async () => {
132	      const r = await findStock(barcode);
133	      const exp = await getNearestExpiry(barcode);
134	      const lots = await listLots(barcode);
135	      if (cancelled) return;
136	      if (!r) return;
137	      setRow(r);
138	      if (seedSource.current === 'remote') return;
139	      // Seed batches from local lots. If lots are empty (legacy row from
140	      // before the lots migration, or a cache that hasn't pulled batches
141	      // yet), synthesise one batch carrying the entire on_hand at the
142	      // cached nearest_expiry. That synthetic row is a placeholder to
143	      // look at, NOT something to save — the JIT fetch below replaces it
144	      // with the server's real breakdown, and Save stays disabled until
145	      // the fetch settles.
146	      const seed: Batch[] = lots.length > 0
147	        ? lots.map((l) => ({ expiry: l.expiry_date, qty: Number(l.qty) }))
148	        : [{ expiry: exp, qty: r.on_hand || 1 }];
149	      // Conflict reference = the earliest expiry actually present in what
150	      // we opened with. Deriving it from the seed rather than reading the
151	      // denormalised nearest_expiry column keeps the two in step even if
152	      // the column lags the lots it summarises — a mismatch here shows up
153	      // as a permanent, unresolvable "Stock has changed" banner.
154	      applySeed(seed, 'local', r.on_hand, earliestExpiry(seed));
155	    })();
156	    return () => { cancelled = true; };
157	  }, [barcode]);
158	
159	  // Fire the JIT fetch independently of the local read so neither
160	  // blocks the other. The 3 s timeout matches CatalogPickerScreen.
161	  useEffect(() => {
162	    let cancelled = false;
163	    const controller = new AbortController();
164	    const t = setTimeout(() => controller.abort(), 3000);
165	    (async () => {
166	      try {
167	        const remote = await api.fetch.stockOne(barcode);
168	        if (cancelled) return;
169	        const remoteQty = Number(remote.on_hand);
170	        const remoteExpiry = remote.nearest_expiry ?? null;
171	        setServerQty(remoteQty);
172	        setServerExpiry(remoteExpiry);
173	
174	        // Take the server's lot breakdown over anything we guessed
175	        // locally. Correcting stock REPLACES the lots, so seeding from a
176	        // cache that had no batches meant saving "one lot, no expiry"
177	        // over the real dated ones — the correction silently wiped the
178	        // expiry for everyone. Only skip this if the guard already
179	        // started editing; their input outranks a late response.
180	        const remoteLots = (remote.lots ?? []).map((l) => ({
181	          expiry: l.expiry_date,
182	          qty: Number(l.qty),
183	        }));
184	        setServerLots(remoteLots.length > 0 ? remoteLots : null);
185	        if (remoteLots.length > 0 && !userTouched.current) {
186	          applySeed(remoteLots, 'remote', remoteQty, remoteExpiry);
187	        }
188	
189	        setVerifyStatus('ok'); // narrowed to 'conflict' below once we know local values
190	      } catch (err) {
191	        if (cancelled) return;
192	        // 404 = no stock row on server; treat as authoritative "absent"
193	        // — the correction will create it. Same UX as a clean ok.
194	        if (err instanceof ApiError && err.status === 404) {
195	          setVerifyStatus('absent');
196	          return;
