83	  // way. A failure here never blocks recording a count: the shelf does
84	  // not stop being countable because the network is down.
85	  const [verifyStatus, setVerifyStatus] = useState<VerifyStatus>('loading');
86	  const [serverQty, setServerQty] = useState<number | null>(null);
87	
88	  /**
89	   * Where the batch rows on screen came from. The local read and the JIT
90	   * fetch race each other, so both consult this instead of assuming an
91	   * order. 'remote' wins and is never downgraded — the server's lot
92	   * breakdown is the real one.
