1	import { nanoid } from 'nanoid/non-secure';
2	import { getDb, now } from './database';
3	
4	export type OutboxKind =
5	  | 'receipt'
6	  | 'product_registration'
7	  | 'issue'
8	  | 'dispense'
9	  | 'reorder_request'
10	  | 'mismatch_flag'
11	  | 'learn_barcode'
12	  | 'stock_correction';
13	
14	export type OutboxRow = {
15	  id: string;
16	  kind: OutboxKind;
17	  payload: string;
18	  status: 'queued' | 'sending' | 'sent' | 'failed';
19	  attempts: number;
20	  last_error: string | null;
21	  created_at: number;
22	  updated_at: number;
23	};
24	
25	export async function enqueue(kind: OutboxKind, payload: object): Promise<string> {
26	  const db = await getDb();
27	  const id = `out_${nanoid(12)}`;
28	  const ts = now();
29	  await db.runAsync(
30	    `INSERT INTO outbox (id, kind, payload, status, attempts, created_at, updated_at)
31	     VALUES (?, ?, ?, 'queued', 0, ?, ?)`,
32	    [id, kind, JSON.stringify(payload), ts, ts]
33	  );
34	  return id;
35	}
36	
37	/**
38	 * Outbox kinds that the user shouldn't see in the Sync Queue UI or
39	 * count in the Home badge. They still flush in the background; they're
40	 * just internal plumbing (e.g. teaching the server a new barcode →
41	 * product alias) that the user never explicitly triggered.
42	 */
43	export const INTERNAL_OUTBOX_KINDS: readonly OutboxKind[] = ['learn_barcode'];
44	
45	export async function pendingCount(): Promise<number> {
46	  const db = await getDb();
47	  const placeholders = INTERNAL_OUTBOX_KINDS.map(() => '?').join(',');
48	  const row = await db.getFirstAsync<{ c: number }>(
