            <Text variant="titleMedium">{session.guardName}</Text>
            <Text
              variant="bodyMedium"
              color={palette.onSurfaceVariant}
              style={{ marginTop: spacing.xs }}
            >
              {t('signedIn')} · {session.language}
            </Text>
            <View style={{ marginTop: spacing.lg }}>
              <Button
                label={t('signOut')}
                variant="outlined"
                onPress={logout}
                size="md"
                fullWidth
              />
            </View>
          </Section>
        )}
      </ScrollView>
    </View>
  );
}

