{item.server_note ? (
  <Text variant="bodyMedium" color={palette.onSurface} style={{ marginTop: spacing.xs }}>
    {item.server_note}
  </Text>
) : null}
{item.last_error ? (
  <Text variant="bodyMedium" color={palette.error} style={{ marginTop: spacing.xs }} numberOfLines={2}>
    {item.last_error}
  </Text>
) : null}

