/**
 * A movement the stock number could not absorb — someone dispensed more
 * than we thought was on the shelf. The record exists because clamping
 * to zero silently would leave the system confidently wrong. An open row
 * is a request to go count the item.
 */
export interface StockDiscrepancy {
  id: string;
  barcode: string;
  product_name: string;
  source_kind: "issue" | "receipt" | "correction";
  source_event_id: string;
  expected_delta: number;
  applied_delta: number;
  shortfall: number;
  status: "open" | "resolved";
  note: string | null;
  observed_at: string | null;
  detected_at: string;
  resolved_at: string | null;
  resolved_by: string | null;
}

export function listDiscrepancies(status: "open" | "resolved" | "all" = "open") {
  return apiRequest<{ discrepancies: StockDiscrepancy[] }>(
    "GET",
    `/api/inventory/discrepancies?status=${status}`,
    undefined,
    SITE_HEADERS,
  );
}

/** Close a recount request. Does NOT change stock — the count itself
 *  arrives separately as a correction from whoever walked to the shelf. */
export function resolveDiscrepancy(id: string) {
  return apiRequest<{ id: string; status: string }>(
    "POST",
    `/api/inventory/discrepancies/${encodeURIComponent(id)}/resolve`,
    undefined,
    SITE_HEADERS,
  );
}

export interface SheetInfo {
  attached: boolean;

