export function InventorySection() {
  const [tab, setTab] = useState<TabKey>("bills");
  const goToTab = (t: TabKey) => setTab(t);

  return (
    <div>
      <section className="panel">
        <div className="panel-title">
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <Warehouse size={20} />
            <div>
              <div style={{ fontSize: 12, color: "var(--muted)", textTransform: "uppercase", letterSpacing: 0.6 }}>
                Operations
              </div>
              <h2 style={{ margin: 0 }}>Inventory</h2>
            </div>
          </div>
        </div>
        <p className="panel-copy">
          Upload vendor bills, resolve unmatched line items, manage the standard product catalog, and export the
          compliance audit log.
        </p>
        <div style={{ display: "flex", gap: 6, borderBottom: "1px solid var(--line)", marginBottom: 14, flexWrap: "wrap" }}>
          <TabButton active={tab === "bills"} onClick={() => setTab("bills")} icon={<Upload size={14} />} label="Upload bill" />
          <TabButton active={tab === "orders"} onClick={() => setTab("orders")} icon={<FileText size={14} />} label="Orders" />
          <TabButton active={tab === "products"} onClick={() => setTab("products")} icon={<FileText size={14} />} label="Catalog" />
          <TabButton active={tab === "stock"} onClick={() => setTab("stock")} icon={<Warehouse size={14} />} label="Stock" />
          <TabButton active={tab === "history"} onClick={() => setTab("history")} icon={<History size={14} />} label="History" />
          <TabButton active={tab === "export"} onClick={() => setTab("export")} icon={<Download size={14} />} label="Export" />
        </div>

        {/* Bill upload stays mounted so an in-progress extraction
            doesn't get wiped when the admin peeks at another tab. The
            extracted list survives until they Discard or Validate. */}
        <div style={{ display: tab === "bills" ? "block" : "none" }}>
          <BillUploadTab goToTab={goToTab} />
        </div>
        {tab === "orders" && <OrdersTab />}
        {tab === "products" && <CatalogTab />}
        {tab === "stock" && <StockTab />}
        {tab === "history" && <HistoryTab />}
        {tab === "export" && <ComplianceTab />}
      </section>
    </div>
  );
}
