/**
 * Recount requests.
 *
 * When a dispense arrives that the stock number cannot cover, the server
 * applies it anyway (the items are physically gone), clamps at zero, and
 * files the shortfall here. That is the whole point of the conflict-free
 * design: the floor user is never asked to arbitrate a number, so the
 * ambiguity has to land somewhere a person can actually act on it.
 *
 * Resolving a row does NOT change stock. It records that someone dealt
 * with it; the real fix is a count, which arrives as its own correction.
 */
function RecountsTab() {
  const qc = useQueryClient();
  const [showResolved, setShowResolved] = useState(false);
  const query = useQuery({
    queryKey: ["inv-discrepancies", showResolved ? "all" : "open"],
    queryFn: () => listDiscrepancies(showResolved ? "all" : "open"),
    staleTime: 30_000,
  });
  const rows: StockDiscrepancy[] = query.data?.data?.discrepancies ?? [];

  const resolveMut = useMutation({
    mutationFn: (id: string) => resolveDiscrepancy(id),
    onSuccess: () => {
      toastSuccess("Recount closed");
      void qc.invalidateQueries({ queryKey: ["inv-discrepancies"] });
    },
    onError: (err) => toastError(errorMessage(err)),
  });

  const fmtWhen = (iso: string | null) => {
    if (!iso) return "—";
    try {
      return new Date(iso).toLocaleString();
    } catch {
      return iso;
    }
  };

  return (
    <div>
      <p className="panel-copy" style={{ marginTop: 0 }}>
        Items where a recorded movement did not fit the stock we had on file. The movement was kept — someone took
        those items off the shelf — so the number needs a physical count to catch up.
      </p>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10, gap: 10 }}>
        <label style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 13, color: "var(--muted)" }}>
          <input
            type="checkbox"
            checked={showResolved}
            onChange={(e) => setShowResolved(e.target.checked)}
          />
          Include closed
        </label>
        <button type="button" onClick={() => void query.refetch()} style={ghostBtn}>
          <RefreshCw size={14} /> Refresh
        </button>
      </div>

      <div style={{ overflowX: "auto" }}>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
          <thead>
            <tr style={{ textAlign: "left", color: "var(--muted)" }}>
              <th style={th}>Detected</th>
              <th style={th}>Product</th>
              <th style={th}>Barcode</th>
              <th style={th}>Asked for</th>
              <th style={th}>Shelf had</th>
              <th style={th}>Short by</th>
              <th style={th}>What happened</th>
              <th style={th}></th>
            </tr>
          </thead>
          <tbody>
            {query.isLoading && (
              <tr>
                <td style={td} colSpan={8}>Loading…</td>
              </tr>
            )}
            {!query.isLoading && rows.length === 0 && (
              <tr>
                <td style={td} colSpan={8}>
                  Nothing to recount. Every movement so far has fitted the stock on file.
                </td>
              </tr>
            )}
            {rows.map((r) => (
              <tr key={r.id} style={{ opacity: r.status === "resolved" ? 0.55 : 1 }}>
                <td style={td}>{fmtWhen(r.detected_at)}</td>
                <td style={td}>{r.product_name}</td>
                <td style={td}>{r.barcode}</td>
                <td style={td}>{Math.abs(r.expected_delta)}</td>
                <td style={td}>{Math.abs(r.applied_delta)}</td>
                <td style={{ ...td, color: "var(--danger, #E53935)", fontWeight: 600 }}>
                  {Math.abs(r.shortfall)}
                </td>
                <td style={td}>{r.note ?? "—"}</td>
                <td style={td}>
                  {r.status === "open" ? (
                    <button
                      type="button"
                      style={ghostBtn}
                      disabled={resolveMut.isPending}
                      onClick={() => resolveMut.mutate(r.id)}
                    >
                      Mark counted
                    </button>
                  ) : (
                    <span style={{ color: "var(--muted)" }}>
                      Closed{r.resolved_by ? ` by ${r.resolved_by}` : ""}
                    </span>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

