  siteId: string;
  barcode: string;
  location: string | null;
}): Promise<boolean> {
  const db = await getDb();
  const result = await db.execute({
    sql: `UPDATE inventory_stock SET location = ?, updated_at = now()
          WHERE site_id = ? AND barcode = ?`,
    args: [input.location, input.siteId, input.barcode],
  });
  return (result.rowsAffected ?? 0) > 0;
}

