/**
 * Inline shelf-label editor.
 *
 * Free text on purpose — sites already label their shelves however they
 * label them, and imposing a taxonomy is the fastest way to guarantee
 * nobody fills it in. Commits on blur or Enter, reverts on Escape.
 * Blank clears the label rather than storing an empty string.
 */
function LocationCell({ barcode, location }: { barcode: string; location: string | null }) {
  const qc = useQueryClient();
  const [value, setValue] = useState(location ?? "");
  const [dirty, setDirty] = useState(false);

  // Follow the server when it changes underneath us, but never clobber
  // something the admin is mid-way through typing.
  useEffect(() => {
    if (!dirty) setValue(location ?? "");
  }, [location, dirty]);

  const mut = useMutation({
    mutationFn: (next: string | null) => setStockLocation(barcode, next),
    onSuccess: () => {
      setDirty(false);
      void qc.invalidateQueries({ queryKey: ["inv-stock-snapshot"] });
    },
    onError: (err) => {
      setValue(location ?? "");
      setDirty(false);
      toastError(errorMessage(err));
    },
  });

  const commit = () => {
    const trimmed = value.trim();
    if (trimmed === (location ?? "")) {
      setDirty(false);
      return;
    }
    mut.mutate(trimmed.length > 0 ? trimmed : null);
  };

  return (
    <input
      type="text"
      value={value}
      placeholder="Set shelf…"
      disabled={mut.isPending}
      onChange={(e) => { setValue(e.target.value); setDirty(true); }}
      onBlur={commit}
      onKeyDown={(e) => {
        if (e.key === "Enter") (e.target as HTMLInputElement).blur();
        if (e.key === "Escape") { setValue(location ?? ""); setDirty(false); }
      }}
      style={{ ...input, width: 120, padding: "4px 8px", fontSize: 12 }}
    />
  );
}

