/**
 * How full the bar is, measured against the REORDER POINT rather than a
 * pack size.
 *
 * The obvious-looking alternative — "347 g of 500 g" — uses pack size as
 * a denominator, which silently breaks the moment someone holds more
 * than one pack (three 500 g packs would read 300%). We have no notion
 * of shelf capacity, and inventing one would mean an admin hand-filling
 * a number for every product before the bar meant anything.
 *
 * Threshold is the number we already have and the one the guard actually
 * cares about: "am I close to needing more?". Full bar at twice the
 * reorder point matches the existing healthy/low colour split, so the
 * bar and the pill can never disagree.
 *
 * Returns null when no reorder point is set — then the bar is hidden
 * rather than drawn against a meaningless zero.
 */
function reorderFill(row: StockRow): number | null {
  if (row.threshold <= 0) return null;
  const comfortable = row.threshold * 2;
  return Math.max(0, Math.min(1, row.on_hand / comfortable));
}

/** "2h ago" / "3d ago". Tells the user whether the number is trustworthy. */
function agoLabel(ts: number, t: (k: StringKey, p?: Record<string, string | number>) => string): string {
  const minutes = Math.floor((Date.now() - ts) / 60000);
  if (minutes < 1) return t('justNow');
  if (minutes < 60) return t('minAgo', { n: minutes });
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return t('hourAgo', { n: hours });
  return t('dayAgo', { n: Math.floor(hours / 24) });
}

