export async function listCanonicalProductsByHsn(
  siteId: string,
  hsnCode: string,
): Promise<CanonicalProduct[]> {
  const db = await getDb();
  const result = await db.execute({
    sql: `SELECT ${CANONICAL_PRODUCT_COLUMNS} FROM canonical_products cp WHERE cp.site_id = ? AND cp.hsn_code = ? ORDER BY cp.canonical_name`,
    args: [siteId, hsnCode],
  });
  return result.rows as CanonicalProduct[];
}

/**
 * True if any barcode mapped to this canonical product has non-zero
 * on_hand or any open lot row. Used by the catalog editor to block a
 * dispense_mode flip while stock exists — flipping changes the unit
 * semantics of `qty`/`on_hand`, which would corrupt history in place.
 */
export async function canonicalProductHasStock(
  productId: string,
): Promise<boolean> {
  const db = await getDb();
  const stockRes = await db.execute({
    sql: `
      SELECT 1
      FROM product_barcodes pb
      JOIN inventory_stock s ON s.site_id = pb.site_id AND s.barcode = pb.barcode
      WHERE pb.product_id = ? AND s.on_hand > 0
      LIMIT 1
    `,
    args: [productId],
  });
  if (stockRes.rows.length > 0) return true;
  const lotRes = await db.execute({
    sql: `
      SELECT 1
      FROM product_barcodes pb
      JOIN inventory_stock_lots l ON l.site_id = pb.site_id AND l.barcode = pb.barcode
      WHERE pb.product_id = ? AND l.qty > 0
      LIMIT 1
    `,
    args: [productId],
  });
  return lotRes.rows.length > 0;
}

// ─── Product Aliases ─────────────────────────────────────────────

