// ── Catalog summary tiles ────────────────────────────────────────────
//
// Each tile is also the filter for what it counts. A separate "Filters"
// control would have meant naming the same four things twice, and the
// number you just read is the most obvious thing to click.

type CatalogFilterKey = "all" | "vendors" | "barcodes" | "nohsn";

function StatTile({
  icon,
  value,
  label,
  tone,
  active,
  onClick,
}: {
  icon: ReactNode;
  value: number;
  label: string;
  tone: string;
  active: boolean;
  onClick: () => void;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      style={{
        flex: "1 1 180px",
        display: "flex",
        alignItems: "center",
        gap: 14,
        padding: "14px 16px",
        textAlign: "left",
        cursor: "pointer",
        background: "var(--surface, #fff)",
        border: `1px solid ${active ? tone : "var(--line)"}`,
        boxShadow: active ? `inset 0 0 0 1px ${tone}` : "none",
        borderRadius: "var(--md-shape-md, 12px)",
      }}
    >
      <span
        style={{
          display: "inline-flex",
          alignItems: "center",
          justifyContent: "center",
          width: 40,
          height: 40,
          borderRadius: "var(--md-shape-sm, 8px)",
          background: `color-mix(in srgb, ${tone} 14%, transparent)`,
          color: tone,
          flexShrink: 0,
        }}
      >
        {icon}
      </span>
      <span style={{ display: "grid", gap: 2, minWidth: 0 }}>
        <span style={{ fontSize: 22, fontWeight: 700, lineHeight: 1.1, color: "var(--text)" }}>
          {value}
        </span>
        <span style={{ fontSize: 12, color: "var(--muted)" }}>{label}</span>
      </span>
    </button>
  );
}

/**
 * Catalog readiness, derived rather than stored.
 *
 * The mockup showed a Status column reading "Active" on every row. We
 * have no status field, and a column that says the same word 248 times
 * carries no information — so this reports whether the product is
 * actually usable end-to-end instead: a barcode to scan at the gate and
 * an HSN for the compliance export. That also makes the column agree
 * with the "With barcodes" and "Missing HSN" tiles above it.
 */
function catalogReadiness(p: CanonicalProduct): { label: string; tone: string; title: string } {
  const missing: string[] = [];
  if (!(p.barcode_count ?? (p.has_barcode ? 1 : 0))) missing.push("barcode");
  if (!p.hsn_code) missing.push("HSN");
  if (missing.length === 0) {
    return { label: "Ready", tone: "var(--green)", title: "Has a barcode and an HSN code" };
  }
  return {
    label: "Needs setup",
    tone: "var(--amber)",
    title: `Missing ${missing.join(" and ")}`,
  };
}

function StatusPill({ label, tone, title }: { label: string; tone: string; title?: string }) {
  return (
    <span
      title={title}
      style={{
        display: "inline-flex",
        alignItems: "center",
        padding: "3px 10px",
        borderRadius: 999,
        fontSize: 11,
        fontWeight: 600,
        whiteSpace: "nowrap",
        color: tone,
        background: `color-mix(in srgb, ${tone} 14%, transparent)`,
      }}
    >
      {label}
    </span>
  );
}

/** Dashed "+ Add …" affordance that reveals its input on click. */
function DashedAddButton({ label, onClick }: { label: string; onClick: () => void }) {
  return (
    <button
      type="button"
      onClick={onClick}
      style={{
        display: "inline-flex",
        alignItems: "center",
        justifyContent: "center",
        gap: 6,
        padding: "9px 16px",
        minHeight: 38,
        border: "1px dashed color-mix(in srgb, var(--md-primary) 55%, transparent)",
        borderRadius: "var(--md-shape-sm, 8px)",
        background: "transparent",
        color: "var(--md-primary)",
        fontSize: 12,
        fontWeight: 600,
        cursor: "pointer",
        whiteSpace: "nowrap",
      }}
    >
      <Plus size={14} /> {label}
    </button>
  );
}

/** Small uppercase section heading used throughout the expanded rows. */
const sectionLabel: React.CSSProperties = {

