}>({ canonical_name: "", category: "Grocery", hsn_code: "", unit: "pcs", pack_size: 1, dispense_mode: 'pack' });
const [filter, setFilter] = useState("");
const [categoryFilter, setCategoryFilter] = useState("all");
const [statFilter, setStatFilter] = useState<CatalogFilterKey>("all");
const [page, setPage] = useState(1);
const [perPage, setPerPage] = useState(20);
const [menuOpen, setMenuOpen] = useState(false);

const barcodeCount = (p: CanonicalProduct) => p.barcode_count ?? (p.has_barcode ? 1 : 0);

/** Counts run over the whole catalog, not the filtered view — the
 *  tiles describe the catalog, and a tile that changed every time you
 *  typed in the search box would be useless as a filter. */
const stats = useMemo(() => ({
  total: products.length,
  vendors: products.filter((p) => (p.alias_count ?? 0) > 0).length,
  barcodes: products.filter((p) => barcodeCount(p) > 0).length,
  noHsn: products.filter((p) => !p.hsn_code).length,
}), [products]);

const categories = useMemo(() => {
  const set = new Set(products.map((p) => p.category).filter(Boolean) as string[]);
  return Array.from(set).sort();
}, [products]);

const filtered = useMemo(() => {
  const q = filter.trim().toLowerCase();
  return products.filter((p) => {
    if (categoryFilter !== "all" && (p.category ?? "") !== categoryFilter) return false;
    if (statFilter === "vendors" && !((p.alias_count ?? 0) > 0)) return false;
    if (statFilter === "barcodes" && !(barcodeCount(p) > 0)) return false;
    if (statFilter === "nohsn" && p.hsn_code) return false;
    if (!q) return true;
    return (
      p.canonical_name.toLowerCase().includes(q) ||
      (p.category ?? "").toLowerCase().includes(q) ||
      (p.hsn_code ?? "").toLowerCase().includes(q)
    );
  });
}, [products, filter, categoryFilter, statFilter]);

// Any change to what's being filtered invalidates the current page.
// Without this, narrowing 248 rows to 3 while on page 7 shows nothing.
useEffect(() => { setPage(1); }, [filter, categoryFilter, statFilter, perPage]);

const pageCount = Math.max(1, Math.ceil(filtered.length / perPage));
const safePage = Math.min(page, pageCount);
const pageStart = (safePage - 1) * perPage;
const paged = filtered.slice(pageStart, pageStart + perPage);

const toggleStat = (key: CatalogFilterKey) =>
  setStatFilter((prev) => (prev === key ? "all" : key));

