  alias: a, productName, onChange, onDelete, deleting,
}: {
  alias: { id: string; raw_name: string; hsn_code: string | null; source: string; confidence: number };
  productName: string;
  onChange: () => void;
  onDelete: () => void;
  deleting: boolean;
}) {
  const [editing, setEditing] = useState(false);
  const [rawName, setRawName] = useState(a.raw_name);
  const [hsn, setHsn] = useState(a.hsn_code ?? "");

  const saveMutation = useMutation({
    mutationFn: () => updateAlias(a.id, {
      raw_name: rawName.trim(),
      hsn_code: hsn.trim() ? hsn.trim() : null,
    }),
    onSuccess: (res) => {
      if (!res.ok) { toastError(errorMessage((res.data as { error?: string }).error, "Save failed")); return; }
      toastSuccess("Alias updated");
      setEditing(false);
      onChange();
    },
    onError: (err) => toastError(err, "Save failed"),
  });

  function cancel() {
    setRawName(a.raw_name);
